/*eslint-disable*/import type{Messages}from"@lingui/core";export const messages=JSON.parse("{\"-C4dIk\":[\"Rätsel, die eine Zwangskette brauchen, sind selten und aufwendig auf Abruf zu finden. Deshalb liefert Suuudokuuu einen mitgelieferten Korpus aus, der bereits von einem Dancing-Links-Exact-Cover-Löser und einem Bitmasken-Löser geprüft, bewertet und vor dem Verpacken auf Zwangsketten-Rätsel gefiltert wurde.\"],\"-Elizp\":[\"Fühlen sich Schnittmengen automatisch an, geh weiter zum <0>druckbaren Sudoku-Heft Schwer</0> für Fish- und Wing-Muster. Geh zurück zu <1>Sudoku Einfach zum Ausdrucken</1> für ein Aufwärmen nur mit Singles, oder spiele Mittelschwer am Bildschirm auf der <2>Seite zu Sudoku Mittelschwer</2>.\"],\"-bYKwe\":[\"Enthält Everest (SE 11,9), Platinum Blonde (SE 10,9) und AI Escargot (SE 10,6).\"],\"-iJ7nh\":[[\"clueCount\"],\" Vorgaben bei 81 Zellen, allein mit letzten freien Zellen und nackten Singles lösbar.\"],\"-vAdwL\":[\"Techniken\"],\"0Ktk6B\":[\"Aktualisiert am <0>\",[\"formattedDate\"],\"</0>\"],\"0L9JZJ\":[\"Wie viele Rätsel enthält das druckbare Sudoku-PDF Einfach?\"],\"0MRfHz\":[\"Sudoku Unendlich\"],\"0RoXsf\":[\"Ist das druckbare Sudoku-PDF Albtraum kostenlos?\"],\"0Sy9Gs\":[\"Wie viele Rätsel enthält das druckbare Sudoku-PDF Hölle?\"],\"0bpi83\":[\"Druckbare Sudoku-Hefte nach Schwierigkeit\"],\"0r_rbI\":[\"Hat \",[\"SITE_NAME\"],\" Werbung?\"],\"0zmlwH\":[[\"title\"],\" herunterladen (PDF)\"],\"18cwop\":[\"<0>Einfach</0> – \",[\"easyClueCount\"],\" Vorgaben; mindestens ein verdecktes Single ist garantiert nötig, aber nie mehr als das.\"],\"1KnfS2\":[\"Wie viele Vorgaben hat ein Albtraum-Sudoku?\"],\"1Lvcgc\":[\"Rätsel 1 aus dem Heft Albtraum, eines von \",[\"PRINTABLE_BOOKLET_SIZE\"],\" im PDF.\"],\"1SEI1B\":[\"Es ist die schwerste erzeugte Stufe von Suuudokuuu, gemessen mit SE \",[\"seRatingRange\"],\" an einer Stichprobe von \",[\"sampleSize\"],\" Rätseln. Jedes davon braucht Ketten- oder Färbelogik zusätzlich zu den Fish- und Wing-Mustern, die schon Schwer verlangt.\"],\"1ZWQlV\":[\"So druckst du diese Rätsel aus\"],\"1ZluOW\":[\"Warum Papier bei Ketten hilft\"],\"1aVkEA\":[\"Eine Schnittmengen-Technik arbeitet mit der Überlappung von einem Block und einer Zeile oder Spalte. Ein Zeigendes Paar oder Zeigendes Triplet findet eine Ziffer, die auf zwei oder drei Zellen eines Blocks beschränkt ist, die alle in einer Linie liegen, und streicht sie im Rest dieser Linie; die Box-Zeilen-Reduktion ist das Spiegelbild und arbeitet von einer Linie zurück in einen Block. Nackte und verdeckte Paare sind der Einstieg in das Denken mit Subsets: zwei Zellen, die genau zwei Kandidaten teilen, oder zwei Ziffern, die in genau zwei Zellen einer Einheit passen – in beiden Fällen sind diese beiden Zellen für alles andere in der Einheit gesperrt. Keine dieser Techniken setzt direkt eine Ziffer, sie streichen nur Kandidaten, doch bei \",[\"clueCount\"],\" Vorgaben wartet in einem mittelschweren Rätsel immer mindestens eine, und meist genügt sie, um ein, zwei Züge später ein neues nacktes Single freizulegen. Auch nach oben ist die Stufe begrenzt: Nichts darin erfordert je einen Fish, einen Wing oder eine Kette, denn ein Rätsel, das das tut, wird stattdessen zu Schwer.\"],\"27Qok0\":[\"Nichts in der Stufe braucht je einen Fish, einen Wing oder eine Kette – ein Rätsel, das das tut, wird stattdessen zu Schwer.\"],\"2Dg4GX\":[\"Wie schwer ist es wirklich?\"],\"2Lb_CG\":[\"Nach verdeckten Singles suchen\"],\"2N-XHb\":[\"Sudoku für Senioren\"],\"2gnUkr\":[\"Anfänger\"],\"2wuXBd\":[\"Prüfe als Allererstes, ob in einem Block, einer Zeile oder Spalte nur eine Ziffer fehlt. Sind in einer Einheit acht der neun Zellen schon gefüllt, muss die neunte Zelle die Ziffer erhalten, die der Einheit noch fehlt – ohne Kandidatenvergleich, einfach durch Subtraktion.\"],\"3-aLmy\":[\"Ja. Beide gehören zur Unendlich-Sammlung, ebenso wie Platinum Blonde und Golden Nugget. Jedes Spiel mischt Ziffern, Zeilen und Spalten neu, sodass das Gitter jedes Mal anders aussieht, während das Rätsel dasselbe bleibt.\"],\"35wRk8\":[\"Es ist die leichteste Stufe von Suuudokuuu, und der Generator garantiert das: Ein Rätsel wird nur dann als Anfänger ausgeliefert, wenn ein Löser, der auf letzte freie Zellen und nackte Singles beschränkt ist, es beendet hat. Unsere Stichprobe misst SE \",[\"seRatingRange\"],\", ohne Kandidatenverfolgung und ohne das Risiko, raten zu müssen.\"],\"367Cn7\":[\"Welche Technik verlangt ein Sudoku-Heft Einfach?\"],\"3DJmkH\":[\"Unsere Technik-Engine stimmt zu, dass diese Rätsel jenseits ihrer Reichweite liegen. Sie kennt jedes Muster im <0>Technikverzeichnis</0> bis hin zu <1/> und <2/> und kann dennoch kein einziges Unendlich-Rätsel allein beenden. Das heißt nicht, dass sie Raten brauchen; es heißt, dass sie längere Zwangsnetze brauchen, als die Engine umsetzt. Hinweise sind bei Albtraum, Hölle und Unendlich standardmäßig aus, und eine Einstellung schaltet sie wieder ein, wenn du die Hilfe der Engine so weit nutzen willst, wie sie reicht.\"],\"3SwmIF\":[\"Startest du ein Unendlich-Spiel, wählt die App eines dieser Rätsel aus und tarnt es. Sie benennt die Ziffern um, mischt Zeilen innerhalb ihrer Bänder, Spalten innerhalb ihrer Türme und die Bänder und Türme selbst und spiegelt das Gitter manchmal an seiner Diagonale. Nichts davon ändert die Logik oder die Bewertung, das Everest, das du spielst, ist also weiterhin Everest, es sieht nur nicht aus wie das Bild unten.\"],\"3a3AKD\":[\"Ist dieses druckbare Sudoku-Heft für Anfänger kostenlos?\"],\"3c-rtT\":[\"Laden im App Store\"],\"3l9jCt\":[\"Wie viele Sudoku-Schwierigkeitsstufen hat Suuudokuuu?\"],\"3m4lq2\":[\"Ein Fish ist auf einem Bildschirm, auf dem nur wenige Zellen auf einmal sichtbar sind, leicht zu übersehen, denn das Muster zeigt sich darin, wo eine Ziffer über zwei, drei oder vier ganze Linien gleichzeitig stehen kann. Auf einem vollständig gedruckten Gitter kannst du die verbleibenden Positionen dieser Ziffer entlang einer Spalte markieren und die Form direkt vom Blatt ablesen. Wings erfordern die umgekehrte Sicht – einige Zellen mit zwei Kandidaten, die sich quer durch das Gitter sehen –, und sie mit Bleistift einzukreisen macht die Überlappung deutlich. Weil beide Familien anfangs leicht falsch angewendet werden, lohnt es sich, die Arbeit jedes Mal mit den Lösungsseiten am Ende zu vergleichen, bis die Form selbstverständlich wird.\"],\"4-X0DJ\":[\"Jetzt bei Google Play\"],\"4DuWbm\":[\"<0>Zeilenregel.</0> Jede der neun Zeilen muss die Ziffern 1 bis 9 genau einmal enthalten.\"],\"4EAgIb\":[\"Leeres Sudoku-Gitter\"],\"4HAVnv\":[\"Jedes Rätsel in diesem Heft stammt aus einem mitgelieferten Korpus, den Suuudokuuu vor der Auslieferung mit zwei unabhängigen Lösungsalgorithmen prüft – einem Dancing-Links-Exact-Cover-Löser und einem Bitmasken-Löser mit Typed Arrays –, sodass für jedes Gitter bestätigt ist, dass es genau eine Lösung hat. Der Korpus schöpft aus dem Katalog der 17-Vorgaben-Rätsel des tdoku-Projekts und der magictour-Liste top1465 schwerer Rätsel, und jedes Rätsel wird beim Verpacken des Korpus auch logisch gelöst und auf der SE-Skala bewertet. Nur Rätsel, deren schwerster Schritt eine Zwangskette ist, bleiben erhalten; alles, was einer Kette, dem Färben oder AIC weicht, wird aussortiert, denn weder die Zahl der Vorgaben noch die Quellenliste allein würde genügen, um ein Höllen-Rätsel zu garantieren. Jedes verbliebene Rätsel lässt sich auf unserer Technikleiter ohne Raten lösen, sodass jedes Rätsel hier garantiert per Logik lösbar ist, noch bevor du zum Bleistift greifst.\"],\"4NMPvd\":[\"Welche Techniken brauche ich für Sudoku Schwer?\"],\"4apI84\":[\"Sudoku in Großdruck zum Ausdrucken\"],\"4gZ5Vw\":[\"Kostenlos und quelloffen unter der \",[\"SITE_LICENSE\"],\"-Lizenz. Keine Werbung, kein Konto, kein Tracking im Spiel – lies <0>warum</0> oder stöbere im <1>vollständigen Quellcode auf GitHub</1>. Apple und das Apple-Logo sind Marken von Apple Inc., eingetragen in den USA und anderen Ländern. App Store ist eine Dienstleistungsmarke von Apple Inc. Google Play und das Google-Play-Logo sind Marken von Google LLC.\"],\"52_TbA\":[\"Fish und Wings auf Papier prüfen\"],\"57DMl6\":[\"Fügen sich die Ketten? Das <0>druckbare Sudoku-Heft Hölle</0> ist die letzte Stufe, in der jedes Rätsel eine Zwangskette braucht. Geh zurück zu <1>Sudoku Schwer zum Ausdrucken</1>, wenn es nur um Fische und Wings gehen soll, oder spiele Albtraum am Bildschirm auf der <2>Seite zu Sudoku Albtraum</2>.\"],\"5D6pgW\":[\"Ein einfaches Rätsel aus demselben Generator wie in der App. Spiele es gleich hier.\"],\"5EmtkG\":[\"Ist das druckbare Sudoku-PDF Hölle kostenlos?\"],\"5YPKNQ\":[\"Wer hat diese Rätsel bewertet?\"],\"5a2b2H\":[\"Sind das Rätsel mit 17 Vorgaben?\"],\"5tWoLs\":[\"Sudoku lernen\"],\"64gfbY\":[\"Sudoku für Anfänger jetzt spielen\"],\"6JHmjr\":[\"Ja. Jedes Gitter wird vor der Auslieferung von einem Dancing-Links-Exact-Cover-Löser und einem Bitmasken-Löser geprüft und hat genau eine Lösung.\"],\"6Y2zqp\":[\"Ist Sudoku Mittelschwer schwer?\"],\"6i2Miv\":[\"Albtraum hat nur \",[\"clueCount\"],\" Vorgaben, und es ist das Heft, in dem sich die gedruckte Seite wirklich bezahlt macht. Jedes Rätsel darin wurde gegen einen Löser getestet, der bereits jeden Fish und jeden Wing kennt – auch den <0>Swordfish</0> und den <1>XY-Wing</1> –, und nur behalten, weil dieser Löser hängen blieb. Beenden lassen sie sich mit Kettenlogik, und eine Kette baut man auf Papier, wo man die Verknüpfungen mit Bleistift einzeichnen und verfolgen kann, weit leichter auf als auf einem engen Bildschirm. Unsere Stichprobe von \",[\"sampleSize\"],\" Rätseln misst die Stufe mit SE \",[\"seRatingRange\"],\".\"],\"6mE7Xy\":[\"Eine Schnittmenge oder ein Paar wird erst sichtbar, wenn man alle verbleibenden Kandidaten einer Zeile, Spalte oder eines Blocks auf einen Blick sieht. Deshalb hilft Papier hier wirklich mehr als ein Bildschirm: Schreibe kleine Ziffern in die Ecke jeder leeren Zelle und suche dann in einer Linie nach einer Ziffer, die in einem Block gefangen ist, oder nach zwei Zellen, die genau zwei Kandidaten teilen. Keines der Muster setzt für sich allein eine Ziffer – beide entfernen nur Kandidaten –, rechne also mit einigen Eliminierungen, bevor ein neues nacktes Single tatsächlich auftaucht. Mit Bleistift statt Kugelschreiber kostet eine falsche Markierung nichts, denn man kann sie radieren.\"],\"6pYHox\":[\"<0>Anfänger.</0> Allein mit letzten freien Zellen und nackten Singles lösbar.\"],\"6tfEbk\":[\"Jedes Rätsel wird von zwei unabhängigen Lösungsalgorithmen auf genau eine Lösung geprüft.\"],\"6yBCvI\":[\"Was ein Rätsel zum Albtraum macht\"],\"6z6usR\":[\"Willst du die Rekordrätsel auf Papier? Lade das <0>druckbare Sudoku-PDF Unendlich</0> herunter. Noch nicht bereit dafür? Geh zurück zu <1>Sudoku Hölle</1>, wo jedes Rätsel eine Zwangskette braucht, aber in Reichweite unserer Technikleiter bleibt. Lies die Geschichten hinter Everest und AI Escargot auf der Seite zu den <2>schwersten Sudoku-Rätseln</2>, vergleiche alle Stufen in der Übersicht <3>Sudoku-Schwierigkeitsstufen</3> oder gehe zurück zur <4>Startseite</4>.\"],\"6zwJ5l\":[\"Einfach liegt zusammen mit Anfänger am unteren Ende der SE-Skala (Sudoku Explainer): Unsere Stichprobe von \",[\"sampleSize\"],\" Rätseln misst SE \",[\"seRatingRange\"],\". Die beiden Stufen teilen sich einen Bereich, weil SE ein verdecktes Single mit 1,5 bewertet, unter einem nackten Single mit 2,3 – die Technik, die Einfach definiert, ist auf dieser Skala also billiger als die, die Anfänger definiert. Was sich wirklich ändert, ist, wo man hinschauen muss: Ein nacktes Single liest man an einer Zelle ab, ein verdecktes Single an einer ganzen Einheit. Das passt zu Spielern, die ein paar Anfänger-Rätsel gelöst haben und eines wollen, das spürbar länger dauert.\"],\"75Y3_I\":[\"Ist AI Escargot im druckbaren Heft enthalten?\"],\"7A3Fmz\":[\"Leichtere Stufe\"],\"7Y8jud\":[\"Sudoku Schwer jetzt spielen\"],\"7Z44bB\":[\"Erkennst du Fische und Wings sicher? Geh weiter zum <0>druckbaren Sudoku-Heft Albtraum</0> für Ketten und Färben. Geh zurück zu <1>Sudoku Mittelschwer zum Ausdrucken</1> für nur Schnittmengen und Subsets, oder spiele Schwer am Bildschirm auf der <2>Seite zu Sudoku Schwer</2>.\"],\"7hktsm\":[\"Erste Schritte\"],\"7lhqPv\":[\"Kurz gesagt\"],\"7r6sCa\":[\"Textgröße\"],\"7z1tpm\":[\"Nein. Der Notizmodus einer App verfolgt Kandidaten für dich, aktualisiert sie beim Eintragen von Ziffern automatisch und lässt dich einen Fehler rückgängig machen, ohne radieren zu müssen.\"],\"83yMJR\":[\"Jede Stufe von Anfänger bis Unendlich hat jetzt einen eigenen Ratgeber, der genau aufschlüsselt, was eine Stufe von der nächsten unterscheidet – Zahl der Vorgaben, nötige Techniken und eine ehrliche Einschätzung, wie schwer sie wirklich ist. Beginne in der Übersicht <0>Sudoku-Schwierigkeitsstufen</0> oder sieh nach, wie sie sich zu den <1>schwersten Rätseln</1> aller Zeiten verhält.\"],\"8GGOmr\":[\"Ein fertig gelöstes Gitter erfüllt alle drei Regeln gleichzeitig. Diese Überlappung macht Sudoku per Logik lösbar: Eine Ziffer, die Zeile, Spalte und Block bereits ausschließen, hat keinen Platz mehr – und darauf beruht fast jede Lösungstechnik. Jede benannte Technik auf dieser Seite, vom einfachsten Single bis zur längsten Kette, ist letztlich nur ein effizienterer Weg, diese Überlappung über viele Zellen gleichzeitig zu verfolgen statt Zelle für Zelle.\"],\"8HgdwA\":[[\"mediumClueCount\"],\" Vorgaben; mit Singles kommt man garantiert nicht weiter, mit Schnittmengen und Subsets schon. Zum digitalen Spielen siehe die <0>Seite zu Sudoku Mittelschwer</0>.\"],\"8bwpsb\":[\"Kostenloses Online-Sudoku bedeutet, das klassische 9×9-Zahlenrätsel im Browser oder in einer App ohne Kauf, Installationslimit oder Paywall zu spielen. \",[\"SITE_NAME\"],\" ist eine kostenlose, quelloffene Umsetzung davon – sieben Schwierigkeitsstufen von Anfänger bis Unendlich, Ratgeber, die Techniken erklären, keine Werbung und kein Tracking im Spiel. Löse im Web oder installiere die App und behalte überall dieselben Serien und Statistiken. Lies <0>warum \",[\"SITE_NAME\"],\" so gebaut ist</0>, dann kennst du die vollständige, überprüfbare Begründung.\"],\"8hKEc0\":[\"FAQ zu Sudoku Albtraum\"],\"8j_b89\":[\"Albtraum endet bei AIC – ein Rätsel, das sich dem widersetzt, liegt jenseits dessen, was die erzeugten Stufen bieten.\"],\"8ko6ZU\":[\"<0>Hölle</0> – mit AIC kommt man garantiert nicht weiter, eine Zwangskette ist nötig; die Rätsel stammen aus einem mitgelieferten, geprüften Korpus und werden nicht für ein Schwierigkeitsband erzeugt.\"],\"8wCnRb\":[\"Die Rätsel sind genau so gedruckt, wie sie veröffentlicht wurden, ohne Umordnung, sodass du dein Gitter mit den Originalen vergleichen kannst, die auf der Seite zu den <0>schwersten Sudoku-Rätseln</0> besprochen werden. Sie werden mit \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite gedruckt, mit Platz für einen vollständigen Satz Bleistiftnotizen, den man braucht: Auf dieser Stufe lassen die meisten Löser jeden Kandidaten eingetragen und testen Ketten auf einem eigenen Blatt. Die letzten Seiten enthalten die fertigen Gitter, sodass du eine lange Gedankenkette prüfen kannst, ohne sie zu Ende führen zu müssen.\"],\"92GEeo\":[\"Erst aufwärmen? Das <0>druckbare Sudoku-Heft Hölle</0> enthält Zwangsketten-Rätsel, die schwer sind, aber in Reichweite unserer Technikleiter bleiben. Lieber am Bildschirm? Spiele dieselben Rekordrätsel auf der <1>Seite zu Sudoku Unendlich</1>, wo jedes Spiel das Gitter neu mischt, oder stöbere in allen Heften auf der <2>Übersicht zu Sudoku zum Ausdrucken</2>.\"],\"93EF2k\":[\"Wie viele Vorgaben hat ein Höllen-Sudoku?\"],\"9AexDe\":[\"Ein Rätsel, das sich mit letzten freien Zellen und nackten Singles allein lösen lässt, wird als zu leicht für die Stufe verworfen.\"],\"9COcEj\":[\"Fish-Muster: X-Wing, Swordfish, Jellyfish und ihre Finned- und Sashimi-Varianten. Wing-Muster: XY-Wing, XYZ-Wing und W-Wing.\"],\"9TF92W\":[\"Unsere Stichprobe von \",[\"sampleSize\"],\" einfachen Rätseln misst SE \",[\"seRatingRange\"],\".\"],\"9e_cYH\":[\"FAQ zu Sudoku für Anfänger\"],\"9qTjdv\":[\"Wie viele Rätsel enthält das druckbare Sudoku-PDF Mittelschwer?\"],\"9rfjS-\":[[\"PRINTABLE_LARGE_PRINT_PAGE_COUNT\"],\" Seiten\"],\"AKA0Xn\":[\"Welche Techniken verlangt dieses Heft Schwer?\"],\"AV85q_\":[[\"clueCount\"],\" Vorgaben bei 81 Zellen, von Anfang bis Ende mit letzten freien Zellen, nackten Singles und verdeckten Singles lösbar.\"],\"AdsNQX\":[\"Ja. Unsere Stichprobe misst die Hölle mit SE \",[\"hellSeRatingRange\"],\", und jedes Unendlich-Rätsel hat eine veröffentlichte Bewertung zwischen \",[\"lowestRatingLabel\"],\" und \",[\"highestRatingLabel\"],\". Höllen-Rätsel weichen unserer Technikleiter noch; Unendlich-Rätsel nicht.\"],\"AfMtNM\":[\"FAQ zu Sudoku Hölle\"],\"Ak9Eh5\":[\"Ein schweres Rätsel aus demselben Generator wie in der App. Spiele es gleich hier.\"],\"B-pBHn\":[\"Kette der Sudoku-Schwierigkeitsstufen\"],\"BJrGt8\":[\"Genau eine Technik. Jedes Anfänger-Rätsel lässt sich mit letzten freien Zellen und nackten Singles beenden; jedes einfache Rätsel nachweislich nicht – es braucht mindestens ein verdecktes Single, um die Blockade zu lösen.\"],\"BZz12Q\":[\"Drucken\"],\"C1_WBQ\":[\"Sudoku ist ein Logikrätsel auf einem 9×9-Gitter, das in neun 3×3-Blöcke unterteilt ist. Ziel ist es, jede leere Zelle mit einer Ziffer von 1 bis 9 zu füllen, sodass sich keine Ziffer in einer Zeile, Spalte oder einem Block wiederholt. Ein wohlgeformtes Sudoku beginnt immer mit einigen bereits gefüllten Zellen – den Vorgaben – und hat immer genau eine gültige Lösung, die allein durch Logik erreichbar ist, ohne zu raten.\"],\"C4kvBI\":[\"Unsere Stichprobe von \",[\"sampleSize\"],\" Höllen-Rätseln misst SE \",[\"seRatingRange\"],\", mit <0/> als häufigstem schwersten Schritt.\"],\"CA7v0X\":[\"Manche dieser Gitter beginnen mit nur \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" Vorgaben und wirken auf den ersten Blick fast leer – die \",[\"PRINTABLE_BOOKLET_SIZE\"],\" Rätsel werden mit \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite und großzügiger Zellgröße gedruckt, damit Platz bleibt, Kandidaten über eine lange Kette von Hand zu verfolgen. Die letzten Seiten enthalten die fertigen Gitter, was auf dieser Stufe fast unverzichtbar ist: Eine Kette von Eliminierungen mit dem Auge zu prüfen ist langsam, und mit einem gedruckten Lösungsschlüssel lässt sich der Endzustand bestätigen, ohne den ganzen Weg neu herzuleiten.\"],\"CAD1qm\":[\"Eine Kette folgt einer abwechselnden Folge starker und schwacher Verknüpfungen. Sie beginnt bei einem Kandidaten und arbeitet sich nach außen vor, bis sie eine Eliminierung oder eine Platzierung beweist, gleichgültig, welcher Zweig zutrifft. Die X-Chain arbeitet mit einer einzigen Ziffer; die XY-Chain folgt stattdessen einem Pfad aus Zellen mit zwei Kandidaten. Einfaches Färben verteilt zwei abwechselnde Farben auf ein Netz starker Verknüpfungen einer Ziffer und streicht jeden Kandidaten, der beide Farben sieht, und AIC verallgemeinert die ganze Familie und mischt Ziffern und Zelltypen in einer durchgehenden Kette. Die Hölle beginnt dort, wo das alles nicht mehr reicht. Eine Zwangskette nimmt einen Kandidaten an – die Möglichkeiten einer Zelle oder die Platzierungen eines Bereichs –, verfolgt alle Folgen und behält nur, was in jedem Zweig gilt; die Seiten zur <0>Nishio</0>-, zur <1>Zellen</1>- und zur <2>Bereichs-Zwangskette</2> führen je ein Beispiel vor. Ein Rätsel kommt nur dann in den Höllen-Korpus, wenn sein schwerster Schritt auf dem bewertungsoptimalen Weg eine Zwangskette ist und unsere Leiter es trotzdem noch zu Ende lösen kann – in der Hölle muss also nie geraten werden.\"],\"CLPF0E\":[\"Die Bewertungen sind die Werte, die unabhängige Rater veröffentlichen, nicht unsere eigenen Messungen.\"],\"ChsZzh\":[[\"hardClueCount\"],\" Vorgaben; mit Subsets kommt man garantiert nicht weiter, mit Fish- und Wing-Mustern schon. Zum digitalen Spielen siehe die <0>Seite zu Sudoku Schwer</0>.\"],\"DE2rA9\":[\"Vorgaben und Schwierigkeit\"],\"DE6q1A\":[\"Ja, konstruktionsbedingt. Albtraum endet bei AIC, und kein Höllen-Rätsel lässt sich mit etwas lösen, das Albtraum erlaubt. Unsere Stichprobe misst die Hölle mit SE \",[\"hellSeRatingRange\"],\" und Albtraum mit SE \",[\"nightmareSeRatingRange\"],\".\"],\"DFi0Zn\":[\"Schwerer als alles andere in der App, und zwar mit großem Abstand. Unsere Stichprobe von \",[\"sampleSize\"],\" <0>Höllen</0>-Rätseln misst SE \",[\"hellSeRatingRange\"],\"; Unendlich beginnt bei \",[\"lowestRatingLabel\"],\". Die Unendlich-Bewertungen sind nicht unsere eigenen Messungen. Der Rater von Suuudokuuu bewertet die SE-Leiter nur bis zu Zwangsketten und Zwangsnetzen und meldet darüber \",[\"SE_RATING_CEILING\"],\" mit einem Obergrenzen-Hinweis; für diese Rätsel nennen wir deshalb die Werte, die unabhängige Rater veröffentlichen, wie der <1>Ratgeber zur Schwierigkeitsbewertung</1> erklärt.\"],\"DIr2XR\":[\"Schnittmengen: Zeigendes Paar, Zeigendes Triplet, Box-Zeilen-Reduktion. Subsets: Nacktes Paar, Verdecktes Paar.\"],\"DRVEbn\":[\"FAQ zum druckbaren Sudoku Hölle\"],\"DRleO8\":[\"<0>Letzte freie Zelle</0> – der einfachste denkbare Zug: die letzte leere Zelle einer Einheit füllen.\"],\"D_b_9m\":[\"FAQ zu Sudoku Einfach\"],\"DgPHNt\":[\"Ein Beinahe-Fish: Die Zeilen oder Spalten bilden einen X-Wing oder <0>Swordfish</0>, bis auf einen oder zwei zusätzliche Kandidaten, die Finne. Die Eliminierung gilt weiterhin, aber nur in den Zellen, die sowohl der Fish als auch die Finne sehen.\"],\"DjGWF0\":[\"Trage alle verbleibenden Kandidaten für die noch leeren Zellen ein und arbeite dann das Technikverzeichnis in der Reihenfolge der Schwierigkeit durch, um weiter Zellen zu lösen.\"],\"Drd4wO\":[\"Eine Ziffer, die auf zwei Zellen eines Blocks beschränkt ist, die auch in einer gemeinsamen Zeile oder Spalte liegen. Sie kann dann im Rest dieser Zeile oder Spalte gestrichen werden, denn eine der beiden Zellen muss sie enthalten.\"],\"DvhSrh\":[[\"clueCount\"],\" Vorgaben bei 81 Zellen; mindestens ein verdecktes Single ist nötig, aber nichts Schwierigeres.\"],\"E5Cz6q\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" Rätsel\"],\"ER15gL\":[\"Ein Unendlich-Rekordrätsel aus derselben kuratierten Sammlung wie in der App, neu gemischt. Spiele es gleich hier.\"],\"ETZyJl\":[\"Sieben Schwierigkeitsstufen von Anfänger über die Hölle bis Unendlich, die oberste Stufe mit Rekordrätseln wie Everest und AI Escargot\"],\"EYQUVy\":[\"<0>Schwer.</0> Mit Subsets kommt man immer ins Stocken, mit einem Fish- oder Wing-Muster geht es immer weiter.\"],\"EYVt4M\":[\"Größte Textgröße\"],\"EyMkmB\":[\"Was ist die leichteste Sudoku-Schwierigkeitsstufe?\"],\"F_APxp\":[\"Kostenloses Offline-Sudoku für iOS, Android und das Web\"],\"FfmJIb\":[\"Ist das druckbare Sudoku-PDF Mittelschwer kostenlos?\"],\"Fgi0TQ\":[\"Nichts im Heft braucht einen Fish, einen Wing oder eine Kette.\"],\"Fv02gG\":[\"Unsere veröffentlichte Stichprobe von \",[\"sampleSize\"],\" schweren Rätseln misst die Stufe mit SE \",[\"seRatingRange\"],\", mit <0/> als häufigstem schwersten Schritt – Werte, die der <1>Ratgeber zur Sudoku-Schwierigkeit</1> direkt misst, statt sie anzunehmen. Die \",[\"PRINTABLE_BOOKLET_SIZE\"],\" Rätsel hier werden mit \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite gedruckt, mit Platz für Kandidaten, und die gelösten Gitter auf den letzten Seiten lassen dich bestätigen, dass eine Fish-Eliminierung tatsächlich gestimmt hat.\"],\"G70CkD\":[\"Wie viele Vorgaben hat ein mittelschweres Sudoku?\"],\"GCBW83\":[\"Löse zuerst die billigsten Platzierungen: erst letzte freie Zellen, dann nackte Singles, dann verdeckte Singles.\"],\"GOSVU9\":[\"Mittelschwere Rätsel haben \",[\"clueCount\"],\" Vorgaben und bleiben garantiert an Singles hängen und lösen sich mit einer Schnittmenge oder einem Subset.\"],\"GRoZ7D\":[\"Sudoku Hölle\"],\"GU9wm2\":[\"Kann ich sie im Unterricht verwenden?\"],\"G_3WRn\":[\"Funktioniert es offline?\"],\"GalvXV\":[\"Unendlich ist die Stufe von Suuudokuuu jenseits der Hölle: eine kuratierte Sammlung der schwersten je veröffentlichten Sudoku-Rätsel, der Rekordgitter, über die die Löser-Community bis heute streitet, kostenlos spielbar. Jedes Unendlich-Rätsel ist ein bekanntes Rätsel mit einer veröffentlichten Sudoku-Explainer-Bewertung (SE) von mindestens \",[\"minimumRatingLabel\"],\" – Arto Inkalas Everest, Platinum Blonde, AI Escargot, Golden Nugget und \",[\"additionalPuzzleCount\"],\" weitere –, das vor der Auslieferung auf eine einzige Lösung geprüft wurde. Das sind die Rätsel, die unser Ratgeber zu den <0>schwersten Sudoku-Rätseln</0> beschreibt; in Unendlich spielst du sie.\"],\"GeGHUl\":[\"Jedes PDF ist auf US Letter eingestellt und mit Vektorlinien und Text gezeichnet, es druckt also in jeder Größe scharf. Öffne die Datei, drucke in 100 % Größe (nicht „An Seite anpassen“, was das Gitter bei manchen Druckern verzerren kann) und drucke einseitig, wenn du die Lösungen getrennt von den Rätseln auf eigenen Blättern behalten möchtest.\"],\"Gfmra_\":[\"Ein einfaches Rätsel zum Einstieg. Spiele es gleich hier oder wähle in der App eine von sieben Schwierigkeitsstufen.\"],\"Gu8Ueq\":[\"Was ein Rätsel zu Unendlich macht\"],\"GzaiWG\":[\"FAQ zur Sudoku-Spielanleitung\"],\"H47ltZ\":[\"Wie drucke ich diese Rätsel aus?\"],\"HCMGUO\":[\"Muss man jemals raten?\"],\"HDn1fw\":[[\"clueCount\"],\" Vorgaben bei 81 Zellen; mindestens ein Fish- oder Wing-Muster jenseits aller Subsets ist garantiert nötig.\"],\"HJEQpI\":[\"Zwischen \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" und \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\". Die Hölle wählt ihre Rätsel nicht nach der Zahl der Vorgaben aus; ein Rätsel qualifiziert sich dadurch, dass es eine Zwangskette braucht, egal wie viele Vorgaben es hat.\"],\"HPogd9\":[\"Warum wird Papier für Kettenrätsel empfohlen?\"],\"HQCVxF\":[\"Ist Anfänger die richtige Stufe für ein Kind oder jemanden, der zum ersten Mal löst?\"],\"HSXkrR\":[\"Ein wohlgeformtes Rätsel hat immer genau eine Lösung und erfordert nie Raten.\"],\"HV3Yoi\":[\"Sudoku Schwer\"],\"Ht078b\":[\"Rätsel 1 aus dem Heft Mittelschwer, eines von \",[\"PRINTABLE_BOOKLET_SIZE\"],\" im PDF.\"],\"I11j00\":[\"Albtraum ist die Expertenstufe von Suuudokuuu – das, was die meisten anderen Apps „sehr schwer“ oder „Experte“ nennen würden. Ein Albtraum-Rätsel hat nur \",[\"clueCount\"],\" Vorgaben bei 81 Zellen, und es ist die Stufe, auf der begrenzte Muster nicht mehr genügen: Jedes Rätsel hier wurde gegen einen Löser geprüft, der bereits jeden Fish und jeden Wing bis zum <0>W-Wing</0> kennt, und wird nur als Albtraum eingestuft, weil dieser Löser hängen blieb. Zum Beenden braucht es Kettenlogik – <1>X-Chain</1>, <2>XY-Chain</2>, <3>Einfaches Färben</3> und <4>AIC</4>, die alternierende Schlusskette, die die anderen drei verallgemeinert.\"],\"I3XIAf\":[\"Lieber am Bildschirm? Spiele jetzt Suuudokuuu\"],\"IANVSf\":[\"Nein. Es gibt nirgends Werbung und kein Tracking im Spiel; diese Website nutzt nur cookielose, anonyme Seitenstatistiken.\"],\"IB9N-i\":[\"Was ist der Unterschied zwischen einer Vorgabe und einem Kandidaten?\"],\"IFKUNe\":[\"Keine Notizen, keine Eliminierungslogik und kein Raten sind für irgendein Rätsel im Heft nötig.\"],\"IOgWqm\":[\"Brett wird geladen …\"],\"I_WAm2\":[\"Ja. Einmal installiert, erzeugt und löst \",[\"SITE_NAME\"],\" Rätsel vollständig auf deinem Gerät und spielt sich daher ohne Verbindung genauso.\"],\"IjDWTu\":[\"So werden die Rätsel geprüft\"],\"IlAsp5\":[\"Mit welcher Sudoku-Schwierigkeit sollte ich anfangen?\"],\"IqBsZ0\":[\"Ja. Das PDF ist kostenlos, ohne Konto und ohne Wasserzeichen, und enthält einen vollständigen Lösungsschlüssel für jedes Rätsel.\"],\"IrAE3z\":[\"Löser\"],\"Iu83qB\":[\"Rätsel 1 aus dem Heft für Anfänger, eines von \",[\"PRINTABLE_BOOKLET_SIZE\"],\" im PDF.\"],\"JBdo3D\":[\"FAQ zu den Sudoku-Schwierigkeitsstufen\"],\"JJoC7U\":[\"Was ein Rätsel schwer macht\"],\"Jrqsp5\":[\"Die Schwierigkeit entsteht hier durch die Technik, die jedes Rätsel braucht, nicht durch die Zahl der Vorgaben.\"],\"JrrSQM\":[\"Was ist der Unterschied zwischen Sudoku für Anfänger und Sudoku Einfach?\"],\"Jry7J2\":[\"Ein Anfänger-Rätsel aus demselben Generator wie in der App. Spiele es gleich hier.\"],\"KDXdKh\":[\"Ein Albtraum-Rätsel aus demselben Generator wie in der App. Spiele es gleich hier.\"],\"KPuUq2\":[\"Kandidaten eintragen, sobald die leichten Zellen ausgehen\"],\"KQe27c\":[\"Sind die Lösungen enthalten?\"],\"KVC9CP\":[\"Das druckbare Sudoku-Heft für Anfänger ist ein kostenloses PDF mit Rätseln mit \",[\"clueCount\"],\" Vorgaben, bei denen sich jede leere Zelle mit einer letzten freien Zelle oder einem nackten Single lösen lässt – eine Eigenschaft, auf die jedes Rätsel geprüft wurde, bevor es ins PDF kam. Es ist das Heft für einen Erstlöser, eine Klasse, die gerade die Regeln lernt, oder alle, die ein Rätsel wollen, das nie einen zweiten Versuch verlangt.\"],\"KiwVTj\":[\"Bietet Suuudokuuu eine Großdruck-Version dieses Hefts an?\"],\"Kmcrz2\":[\"Ja. \",[\"SITE_NAME\"],\" ist kostenlos und quelloffen, ohne In-App-Käufe, Abos oder kostenpflichtige Schwierigkeitsstufen.\"],\"L0XezG\":[\"Was ein Rätsel zur Hölle macht\"],\"L36iW5\":[\"Ja. Der Code von Suuudokuuu, einschließlich des Generators hinter diesen Rätseln, ist unter der MIT-Lizenz quelloffen, und diese Website schränkt das Ausdrucken oder Weitergeben der PDFs nicht ein – auch nicht im Unterricht, in einer Nachhilfestunde oder in einem Arbeitsblatt-Paket.\"],\"L3TeBG\":[\"Wie schwer ist Sudoku für Anfänger?\"],\"LBVuWJ\":[\"Sudoku für Anfänger\"],\"LDOq68\":[\"Wie viele Rätsel enthält das druckbare Sudoku-PDF Albtraum?\"],\"LI4SwS\":[\"Was ein Rätsel mittelschwer macht\"],\"LNoRL7\":[\"<0>Einfach.</0> Kommt um verdeckte Singles hinzu, noch ohne dass Kandidaten notiert werden müssen.\"],\"LfQJwZ\":[\"Ein Deckblatt nennt vorab die Anzahl der Rätsel und Seiten, dann folgen \",[\"PRINTABLE_BOOKLET_SIZE\"],\" Rätsel mit \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite, sodass auf einem Blatt \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" vollständige Gitter stehen. Die letzten Seiten enthalten alle gelösten Gitter im gleichen Layout, sodass man zum Überprüfen einer Antwort nie in einem anderen Seitenformat suchen muss. Die ganze Datei besteht aus Vektorgrafik und einer Standard-PDF-Schrift und druckt daher in jeder vom Drucker unterstützten Größe sauber. Unsere veröffentlichte Stichprobe von \",[\"sampleSize\"],\" einfachen Rätseln misst SE \",[\"seRatingRange\"],\" – Werte, die der <0>Ratgeber zur Sudoku-Schwierigkeit</0> direkt misst, statt sie anzunehmen.\"],\"LrHydF\":[\"Lies die <0>Spielanleitung</0> für die drei Regeln und eine Schritt-für-Schritt-Erklärung deiner ersten Züge, oder schlage einen beliebigen Begriff im <1>Sudoku-Glossar</1> nach, das jede Technik und jeden Fachbegriff der Ratgeber erklärt.\"],\"Lxq-zS\":[\"Sudoku in Großdruck\"],\"M1Yfw6\":[\"Mindestens ein <0>verdecktes Single</0> pro Rätsel, zusätzlich zu den letzten freien Zellen und nackten Singles, die schon Anfänger nutzt, und nichts Schwierigeres.\"],\"MLFx1h\":[\"Ja. Einfach ist die Ausgangsstufe für das Großdruck-PDF mit \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" Rätseln und größeren Zellen für Leser, die mehr Platz zum Schreiben wollen.\"],\"MREaAq\":[\"Alles, was Mittelschwer braucht, plus mindestens ein Fish- oder Wing-Muster: X-Wing, Swordfish, Jellyfish, ihre Finned- und Sashimi-Varianten, XY-Wing, XYZ-Wing oder W-Wing. Eines davon ist immer nötig, denn ein Rätsel, das keines braucht, wird stattdessen als Mittelschwer eingestuft.\"],\"MVYMfh\":[\"Sudoku-Schwierigkeitsgrade\"],\"M_zq3f\":[\"FAQ zum druckbaren Sudoku Unendlich\"],\"Mz7rRO\":[\"Prüfe jede Zeile, Spalte und jeden Block, in denen bereits acht der neun Zellen gefüllt sind, und trage die fehlende Ziffer in die leere Zelle ein.\"],\"N0hmpU\":[[\"clueCount\"],\" Vorgaben bei 81 Zellen – nur eine weniger als bei Mittelschwer. Genau deshalb wird die Stufe über die nötigen Techniken definiert und nicht über die Zahl der Vorgaben.\"],\"NQTfla\":[\"FAQ zum druckbaren Sudoku für Anfänger\"],\"NeWjyh\":[\"<0>Anfänger</0> – \",[\"newbieClueCount\"],\" Vorgaben, allein mit letzten freien Zellen und nackten Singles lösbar.\"],\"NkdmkS\":[\"Welche Techniken verlangt dieses Heft Albtraum?\"],\"Nq65SI\":[\"Nein. Zahl der Vorgaben und Schwierigkeit sind getrennte Tatsachen – siehe den <0>Ratgeber zu 17-Vorgaben-Sudokus</0>. Diese Rätsel sind schwer, weil jedes eine Zwangskette braucht, nicht wegen der Zahl der Vorgaben, mit denen sie beginnen.\"],\"NuoZju\":[\"Ein Höllen-Rätsel gelöst und willst mehr? <0>Sudoku Unendlich</0> bietet die Rekordrätsel – Everest, Platinum Blonde, AI Escargot –, die selbst unsere Zwangsketten übersteigen. Noch nicht bereit für Ketten? Geh zurück zu <1>Sudoku Albtraum</1>, das dieselbe Logik verlangt, bei mehr vorgegebenem Gitter. Lieber auf Papier? Lade das <2>druckbare Sudoku-PDF Hölle</2> herunter. Stöbere im <3>Technikverzeichnis</3>, besonders bei X-Chain, XY-Chain, Einfachem Färben und AIC, in der <4>Spielanleitung</4>, im <5>Ratgeber zu 17-Vorgaben-Sudokus</5>, in der Übersicht <6>Sudoku-Schwierigkeitsstufen</6> mit allen Stufen oder gehe zurück zur <7>Startseite</7>.\"],\"Nyd-0x\":[\"Wie viele Vorgaben hat ein schweres Sudoku?\"],\"NzFVBG\":[\"Warum lassen sich Fish und Wing auf Papier leichter prüfen?\"],\"OMs2n2\":[\"Bereit, Eliminierungen zu verketten, statt Formen zu erkennen? Geh weiter zu <0>Sudoku Albtraum</0> oder zurück zu <1>Sudoku Mittelschwer</1> für ein Rätsel mit Schnittmengen und Subsets. Lieber auf Papier? Lade das <2>druckbare Sudoku-PDF Schwer</2> herunter. Sieh dir das <3>Technikverzeichnis</3>, die <4>Spielanleitung</4>, alle Stufen in der Übersicht <5>Sudoku-Schwierigkeitsstufen</5> an oder gehe zurück zur <6>Startseite</6>.\"],\"OubwsB\":[\"Wie viele Rätsel enthält das druckbare Sudoku-PDF für Anfänger?\"],\"P2bU2d\":[\"Was ein Rätsel einfach macht\"],\"P6JVwt\":[\"Selten. Die meisten Spieler können die wenigen Kandidaten, die ein verdecktes Single braucht, im Kopf verfolgen, aber sie aufzuschreiben schadet in einer volleren Zeile nie.\"],\"PDbaU0\":[\"Brauche ich Notizen für Anfänger-Rätsel?\"],\"PFKt-9\":[\"Schwer fällt auf \",[\"clueCount\"],\" Vorgaben, und dies ist das erste druckbare Heft auf der Seite, in dem Subsets allein nicht bis zum Ende reichen. Jedes Rätsel darin wurde gegen einen Löser getestet, der bereits jede Schnittmenge und jedes Subset kennt, und nur behalten, weil dieser Löser hängen blieb. Beenden lassen sie sich mit einem Fish oder einem Wing: dem <0>X-Wing</0> und seinen größeren und Finned-Verwandten oder einem der Wing-Muster mit zwei Kandidaten.\"],\"PGxh1d\":[\"Was ist ein Finned Fish im Sudoku?\"],\"PKS4Or\":[\"Ist das druckbare Sudoku-PDF Unendlich kostenlos?\"],\"PYziuK\":[\"Eine Kette hat keine feste Form und wird Glied für Glied aufgebaut. Das lässt sich viel leichter nachvollziehen, wenn man jede starke und schwache Verknüpfung aufschreibt, als auf einem kleinen Bildschirm zu scrollen.\"],\"PZQD8F\":[\"Jetzt spielen\"],\"Pbm-BS\":[\"Wie garantiert Suuudokuuu die Technikanforderung einer Stufe?\"],\"PdMLK1\":[\"Arto Inkalas Everest (2012), 21 Vorgaben, veröffentlicht mit SE 11,9.\"],\"Pg0uLs\":[\"Jede Stufe ist kostenlos spielbar, ohne Werbung und ohne Anmeldung. <0>Spiele jetzt ein Rätsel</0> in einer der sieben Stufen oder lies die vollständige Aufschlüsselung der Vorgaben und nötigen Techniken in der Übersicht <1>Sudoku-Schwierigkeitsstufen</1>. Du willst auf Papier lernen? Beginne mit dem <2>druckbaren Anfänger-Sudoku als PDF</2>.\"],\"PgRaz8\":[\"Sudoku Einfach jetzt spielen\"],\"PivQ2i\":[\"Sehr. Jedes Rätsel der Unendlich-Sammlung hat eine veröffentlichte SE-Bewertung von mindestens \",[\"lowestRatingLabel\"],\", weit jenseits von allem, was die erzeugten Stufen oder der Höllen-Korpus liefern. Unser eigener Rater hört bei \",[\"SE_RATING_CEILING\"],\" auf, die SE-Leiter zu bewerten, daher stammen die hier genannten Werte von unabhängigen Ratern, und unsere Technik-Engine kann keines dieser Gitter allein beenden. Rechne mit langen Zwangsketten und Zwangsnetzen und damit, dass ein einzelnes Rätsel weit länger dauert als alles andere auf dieser Seite.\"],\"Pqhtap\":[\"Einfach\"],\"PrxlWP\":[\"FAQ zum druckbaren Sudoku Einfach\"],\"PszyWW\":[\"Wie wird man am schnellsten besser im Sudoku?\"],\"PzS0uu\":[\"Schwere Rätsel haben \",[\"clueCount\"],\" Vorgaben und brauchen garantiert mindestens ein Fish- oder Wing-Muster jenseits aller Subsets.\"],\"Q5B0cW\":[\"Hölle\"],\"QBE_L9\":[\"<0>Albtraum.</0> Mit Fischen und Wings kommt man immer ins Stocken, mit Ketten- oder Färbelogik geht es immer weiter.\"],\"Qo4hE6\":[\"Eine Kette folgt einer abwechselnden Folge starker und schwacher Verknüpfungen zwischen Kandidaten. Man beginnt an einem Ende und schließt nach außen, bis die beiden Enden eine Eliminierung beweisen, gleichgültig, welches von beiden wahr ist. Die X-Chain arbeitet dabei mit einer einzigen Ziffer; die XY-Chain läuft stattdessen über einen Pfad aus Zellen mit zwei Kandidaten und wechselt bei jedem Schritt die Ziffer. Einfaches Färben verteilt zwei abwechselnde Farben auf ein Netz starker Verknüpfungen einer Ziffer und streicht jeden Kandidaten, der beide Farben sieht. AIC fasst alle zusammen und mischt Ziffern und Verknüpfungsarten in einer einzigen durchgehenden Kette. Der Unterschied zu einem Fish oder einem Wing liegt nicht in der Raffinesse, sondern in der Form: Ein Wing ist eine feste Anordnung aus drei oder vier Zellen, die man wiedererkennen lernt, eine Kette hat dagegen keine feste Größe und muss Zug für Zug aufgebaut werden. Albtraum endet bei AIC – alles, was sich dem noch widersetzt, liegt jenseits dessen, was die erzeugten Stufen bieten.\"],\"R1g33v\":[\"Kein Rätsel, nur das Gitter: ein ganzseitiges 9×9-Gitter zum Abschreiben eines Rätsels aus einem Buch oder einer Zeitung, dazu eine zweite Seite mit vier kleineren Gittern für schnelle Übungsblätter. Nützlich für Lehrkräfte, die eigene Arbeitsblätter bauen, oder für alle, die ein Rätsel abschreiben, das sie ohne druckfreundliche Version irgendwo gefunden haben.\"],\"RJUjbN\":[\"Tipps zum Lösen mit Bleistiftnotizen\"],\"RMq7iB\":[\"Ein Fish betrachtet eine Ziffer über mehrere Linien hinweg. Der X-Wing ist der kleinste: Eine Ziffer, die in zwei Zeilen auf dieselben zwei Spalten beschränkt ist, kann im Rest dieser Spalten gestrichen werden, denn welche Zeile sie auch erhält, die Spalten sind bereits festgelegt. Ein <0>Swordfish</0> überträgt dieselbe Idee auf drei Linien, ein Jellyfish auf vier. Finned- und Sashimi-Varianten lockern das Grundmuster, indem sie einen zusätzlichen Kandidaten erlauben, der eine kleinere, sichere Eliminierung weiterhin stützt, wenn man ihn berücksichtigt – und in unserer Stichprobe treten sie weit häufiger auf als die Lehrbuchformen. Wings funktionieren anders: Ein XY-Wing verbindet drei Zellen mit zwei Kandidaten, sodass ein Kandidat, den zwei von ihnen teilen, überall gestrichen werden kann, wo beide ihn sehen; der XYZ-Wing gibt dem Dreh- und Angelpunkt diesen Kandidaten ebenfalls, und der W-Wing verbindet zwei gleiche Zellen mit zwei Kandidaten über eine starke Verknüpfung einer gemeinsamen Ziffer. Schwer endet beim W-Wing: Ein Rätsel, das nach allen Fischen und Wings noch immer nicht weitergeht, ist ein Albtraum-Rätsel und kein schweres.\"],\"RRGDQM\":[\"Anfänger ist die leichteste der sieben Stufen von Suuudokuuu; es folgen Einfach, Mittelschwer, Schwer, Albtraum, Hölle und Unendlich in aufsteigender Schwierigkeit.\"],\"Rj2Y_n\":[\"Die bekanntesten Infinity-Gitter haben eigene Seiten, jeweils spielbar, druckbar und von der Engine Schritt für Schritt gelöst: <0>AI Escargot</0>, <1>Golden Nugget</1>, <2>Platinum Blonde</2>, <3>Everest</3>, <4>Kolk</4> und <5>Silver Plate</5>.\"],\"Rwv4vE\":[\"Auf jedem Rätsel eine Zwangskette, zusätzlich zu den Ketten, dem Färben, den Fischen, Wings und Subsets, die schon die früheren Stufen verlangen. X-Chain, XY-Chain, Einfaches Färben und AIC bringen dich weit, aber nie ganz bis zum Ziel; eine <0>Nishio-Zwangskette</0> ist meist der Weg aus der Sackgasse.\"],\"SPFeoH\":[\"FAQ zum druckbaren Sudoku Schwer\"],\"ScJ9fj\":[\"Datenschutzerklärung\"],\"Sg-BY5\":[\"Die Zahl der Vorgaben ist nicht die Schwierigkeit. Sie ist nur die Eingabe: Weniger Startziffern bedeuten weniger sofortige Platzierungen, und das zwingt den Löser – Mensch oder Maschine –, auf mehr benannte Techniken zurückzugreifen, bevor sich das Gitter wieder bewegt. Suuudokuuu entfernt Ziffern aus einem gelösten Gitter bis zu einem Zielwert pro Stufe, prüft, dass das Ergebnis weiterhin genau eine Lösung hat, und macht dann das, was die Stufe tatsächlich definiert: Es löst das Rätsel zweimal, einmal mit der Technikleiter der darunterliegenden Stufe und einmal mit der eigenen, und behält es nur, wenn die erste Lösung scheitert und die zweite gelingt. Rätsel, die das verfehlen, werden verworfen und ein neues wird erzeugt. Deshalb ist jede Stufe oben als Garantie formuliert und nicht als Hoffnung. Das <0>vollständige Technikverzeichnis</0> listet jedes Muster dieser Leiter auf, in der Reihenfolge, in der ein Löser es versucht. Innerhalb eines Bands können sich zwei Rätsel trotzdem stark unterscheiden – <1>Vorgaben und Schwierigkeit</1> misst genau, wie stark.\"],\"Sjq7vw\":[\"Schließe für jede verbleibende leere Zelle alle Ziffern aus, die in ihrer Zeile, Spalte und ihrem Block schon vorkommen. Bleibt genau eine Ziffer übrig, trage sie ein.\"],\"T5khAF\":[\"Sudoku Hölle jetzt spielen\"],\"T91vKp\":[\"Spielen\"],\"TW-b-m\":[\"Nein. Die Zahl der Vorgaben ist nur die Eingabe, die einen Löser zu einem breiteren Technikspektrum zwingt; das vom Generator geprüfte Technikband ist es, was jede Stufe tatsächlich definiert. Der Ratgeber <0>Vorgaben und Schwierigkeit</0> misst diese Lücke direkt.\"],\"T_JQXy\":[\"Unsere Stichprobe von \",[\"sampleSize\"],\" mittelschweren Rätseln misst SE \",[\"seRatingRange\"],\".\"],\"T_R-Qz\":[\"Hauptnavigation\"],\"TiHBaL\":[\"Sudoku Schwer ist eine Schwierigkeitsstufe, die bei \",[\"clueCount\"],\" Vorgaben bei 81 Zellen beginnt und dadurch definiert ist, was ein Löser nur mit Subsets nicht beenden kann: Jedes Rätsel der Stufe wurde durch einen Löser geschickt, der jede Schnittmenge und jedes Subset bis zum <0>verdeckten Quadrupel</0> beherrscht, und nur behalten, weil dieser Löser hängen blieb. Die Blockade löst ein Fish – <1>X-Wing</1>, <2>Swordfish</2>, <3>Jellyfish</3> und ihre <4>Finned</4>- und <5>Sashimi</5>-Varianten – oder ein Wing: <6>XY-Wing</6>, <7>XYZ-Wing</7> und <8>W-Wing</8>.\"],\"TqC0fH\":[[\"clueCount\"],\" Vorgaben bei 81 Zellen, und jede leere Zelle lässt sich mit einer letzten freien Zelle oder einem nackten Single lösen.\"],\"U1U2tC\":[\"Wie viele Vorgaben hat ein einfaches Sudoku?\"],\"U2AKxD\":[\"FAQ zu Sudoku zum Ausdrucken\"],\"U9wBFD\":[\"Einfach bleibt bei Logik nur mit Singles und ist damit weiterhin anfängerfreundlich. Die einzige zusätzliche Fähigkeit gegenüber Anfänger ist, eine Ziffer zu erkennen, die in einer Einheit nirgendwo sonst hinpasst.\"],\"UF5_iX\":[\"Standard-Textgröße\"],\"UILsns\":[\"Trage Kandidaten in eine Zelle erst ein, wenn das Absuchen keine Platzierungen mehr liefert.\"],\"Umo747\":[\"Notizen, Eliminierungslogik und Raten sind nie nötig.\"],\"Uq9L94\":[[\"clueCount\"],\" Vorgaben bei 81 Zellen, deutlich weniger als ein Drittel des Gitters.\"],\"UveQZj\":[\"Unsere Stichprobe von \",[\"sampleSize\"],\" Albtraum-Rätseln misst SE (Sudoku Explainer) \",[\"seRatingRange\"],\", mit <0/> als häufigstem schwersten Schritt. AIC ist hier die Obergrenze: Jedes Albtraum-Rätsel fällt ihm zum Opfer, und die <1>Stufe Hölle</1> beginnt genau dort, wo es endet, mit Rätseln, die eine Zwangskette brauchen. Manche dieser Höllen-Rätsel haben mehr Vorgaben als Albtraum, was auf dieser Seite der klarste Beleg dafür ist, dass Zahl der Vorgaben und Schwierigkeit getrennte Tatsachen sind. Die gemessenen Tabellen stehen in unserem <2>Ratgeber zur Sudoku-Schwierigkeit</2>. Qualitativ geht es hier nicht mehr um Tempo, sondern darum, eine ganze Kette von Folgerungen im Kopf zu halten, ohne den Faden zu verlieren.\"],\"V9j1Oq\":[\"Nein. Jedes Rätsel der Stufe wird vor der Auslieferung als mit der Technikleiter bis AIC lösbar bestätigt, es gibt also immer eine vollständige Kette – sie zu finden ist die Arbeit.\"],\"VHv3Qz\":[\"Unendlich-Rätsel haben \",[\"INFINITY_MINIMUM_GIVEN_COUNT\"],\" bis \",[\"INFINITY_MAXIMUM_GIVEN_COUNT\"],\" Vorgaben und werden von zwei unabhängigen Lösungsalgorithmen auf eine einzige Lösung geprüft.\"],\"VT7jaN\":[\"Ein Höllen-Rätsel aus demselben geprüften Korpus wie in der App. Spiele es gleich hier.\"],\"VUJcE0\":[\"Ja. Jedes Rätsel im Heft ist allein mit einer letzten freien Zelle oder einem nackten Single lösbar, sodass nie Kandidatennotizen oder Eliminierungslogik nötig sind.\"],\"Vmq46x\":[\"Fühlen sich letzte freie Zellen und nackte Singles automatisch an, geh weiter zum <0>druckbaren Sudoku-Heft Einfach</0>, das genau eine Technik ergänzt: das verdeckte Single. Um Anfänger-Rätsel stattdessen am Bildschirm zu spielen, besuche die <1>Seite zu Sudoku für Anfänger</1>. Die vollständige Technikleiter und die gemessenen Daten hinter diesen Aussagen findest du im <2>Technikverzeichnis</2> und im <3>Ratgeber zur Sudoku-Schwierigkeit</3>.\"],\"W1nEnp\":[[\"clueCount\"],\" Vorgaben bei 81 Zellen: Schon vor dem ersten Zug ist ein Drittel des Gitters ausgefüllt.\"],\"W8o5ac\":[\"Die anderen Stufen sind durch die Techniken definiert, die sie verlangen. Unendlich wird durch Ruf definiert, und zwar gemessenen: Ein Rätsel qualifiziert sich nur, wenn unabhängige Rater dafür eine SE-Bewertung von \",[\"minimumRatingLabel\"],\" oder höher veröffentlicht haben. Die meisten der \",[\"infinityCorpusSize\"],\" stammen aus einem Stand von 2011 der Datenbank der schwersten Rätsel, die die Sudoku-Löser-Community pflegt; der Rest sind die benannten Klassiker aus den Forenbeiträgen und Veröffentlichungen, in denen sie zuerst erschienen. Bevor die Sammlung in die App gepackt wird, bestätigen ein Dancing-Links-Exact-Cover-Löser und ein Bitmasken-Löser, dass jedes Gitter genau eine Lösung hat.\"],\"W9xBMf\":[\"Wer neu beginnt, startet bei Anfänger und steigt Stufe für Stufe auf; jeder Schritt fügt gegenüber der Stufe darunter genau eine neue Technik hinzu, bis hinauf zu Schwer. Lies zuerst die <0>Spielanleitung</0>, wenn dir die drei Grundregeln noch nicht vertraut sind.\"],\"WB-pGD\":[\"Dieses Heft druckt \",[\"PRINTABLE_BOOKLET_SIZE\"],\" der schwersten je veröffentlichten Sudoku-Rätsel aus der Stufe Unendlich von Suuudokuuu: Arto Inkalas Everest, AI Escargot, Platinum Blonde, Golden Nugget und weitere Rekordgitter, jedes mit einer veröffentlichten SE-Bewertung (Sudoku Explainer) zwischen \",[\"lowestRatingLabel\"],\" und \",[\"highestRatingLabel\"],\". Jedes hat genau eine Lösung, und die gelösten Gitter stehen hinten.\"],\"WG8Ftb\":[\"Wie viele Vorgaben hat ein Anfänger-Rätsel?\"],\"WTwN7-\":[[\"SITE_NAME\"],\" spielen\"],\"WmW-Gm\":[\"Druckfläche ist hier wichtiger als bei den leichteren Stufen, weil Schnittmengen und Paare dadurch funktionieren, dass man Kandidaten am Rand markiert. Die \",[\"PRINTABLE_BOOKLET_SIZE\"],\" Rätsel werden mit \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite in voller Zellgröße gedruckt und lassen um jede Ziffer genug Platz, um die kleinen Zahlen einzutragen, über die eine Schnittmenge oder ein Paar urteilt. Gelöste Gitter schließen die Datei ab, damit du deine Kandidatennotizen mit einer bestätigten Antwort vergleichen kannst. Unsere veröffentlichte Stichprobe von \",[\"sampleSize\"],\" mittelschweren Rätseln misst SE \",[\"seRatingRange\"],\" – Werte, die der <0>Ratgeber zur Sudoku-Schwierigkeit</0> direkt misst, statt sie anzunehmen.\"],\"WrhTzj\":[\"Ja. Jedes Stufen-Heft und der Großdruck-Satz enthalten auf den letzten Seiten die vollständigen gelösten Gitter, erzeugt von demselben Löser, der vor der Auslieferung prüft, dass jedes Rätsel genau eine Lösung hat.\"],\"WwMVff\":[\"Wie schwer ist Sudoku Albtraum?\"],\"XGVJW3\":[\"Sudoku-Glossar\"],\"XORYRH\":[\"Die \",[\"PRINTABLE_BOOKLET_SIZE\"],\" Rätsel werden mit \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite gedruckt, so bemessen, dass auch eine Kette über das ganze Gitter bequem auf ein Blatt passt. Vollständig gelöste Gitter schließen das Heft ab, was hier wichtiger ist als bei den leichteren Stufen – eine einzige übersehene Eliminierung mitten in einer Kette wirkt sich schnell aus, und ein gedruckter Lösungsschlüssel fängt sie ab. Die gemessene Streuung hinter diesen Aussagen steht im <0>Ratgeber zur Sudoku-Schwierigkeit</0>.\"],\"XpU6Tm\":[\"Warum nutzt die Hölle einen festen Rätselkorpus, statt Rätsel zu erzeugen?\"],\"XzG50N\":[\"Die Hölle ist die schwerste technikbasierte Stufe von Suuudokuuu – das, was die meisten Mitbewerber „böse“ oder „extrem“ nennen. Ein Höllen-Rätsel wird durch die Logik definiert, die es verlangt, nicht durch die geringe Zahl seiner Vorgaben: Kein Höllen-Rätsel lässt sich mit einer Technik beenden, die Albtraum erlaubt, also braucht jedes eine Zwangskette. Anders als die erzeugten Stufen stammt die Hölle aus einem mitgelieferten Korpus veröffentlichter schwerer Rätsel, der vor der Auslieferung von zwei unabhängigen Lösern geprüft wird, und jedes Rätsel lässt sich auf unserer Technikleiter weiterhin ohne Raten lösen. Rechne damit, zuerst jedes Ketten- und Färbemuster zu nutzen – <0>X-Chain</0>, <1>XY-Chain</1>, <2>Einfaches Färben</2> und <3>AIC</3> –, bevor eine Zwangskette die Blockade löst.\"],\"Y3fLpk\":[\"Wie viele Rätsel enthält das druckbare Sudoku-PDF Schwer?\"],\"YGCzAJ\":[\"Jedes Kandidatenrätsel wird zweimal gelöst: einmal mit der Technikleiter der darunterliegenden Stufe, was scheitern muss, und einmal mit der eigenen Leiter, was gelingen muss. Rätsel, die einen der beiden Tests verfehlen, werden verworfen und neu erzeugt.\"],\"YM-Le2\":[[\"clueCount\"],\" Vorgaben bei 81 Zellen; mindestens eine Ketten- oder Färbetechnik jenseits aller Fische und Wings ist garantiert nötig.\"],\"Y_LLdr\":[\"Ist das druckbare Sudoku-PDF Einfach kostenlos?\"],\"Yj1j4Z\":[\"Rätsel 1 aus dem Heft Hölle, eines von \",[\"PRINTABLE_BOOKLET_SIZE\"],\" im PDF.\"],\"YjxNca\":[\"Sudoku Unendlich jetzt spielen\"],\"Z-7bqV\":[\"FAQ zu Sudoku Schwer\"],\"Z9Mfy1\":[\"Was im Heft steckt\"],\"Z9MhMF\":[\"Was ein Rätsel zum Anfänger-Rätsel macht\"],\"ZBT6Lr\":[[\"infinityCorpusSize\"],\" Rekordrätsel mit \",[\"INFINITY_MINIMUM_GIVEN_COUNT\"],\" bis \",[\"INFINITY_MAXIMUM_GIVEN_COUNT\"],\" Vorgaben, veröffentlicht mit SE \",[\"lowestRatingLabel\"],\" bis \",[\"highestRatingLabel\"],\".\"],\"ZPXer3\":[\"Notizen und Kandidaten\"],\"Zm7CE_\":[\"Jede Technik, mit der \",[\"SITE_NAME\"],\" Hinweise erzeugt, ist mit einem Beispielbrett dokumentiert, das direkt aus der Löse-Engine stammt. Beginne mit dem <0>vollständigen Technikverzeichnis</0> oder springe zu einem der ersten Muster, die die meisten Spieler lernen.\"],\"ZtZST0\":[\"Jedes Rätsel braucht eine Zwangskette und stammt aus unserem mitgelieferten, geprüften Höllen-Korpus. Zum digitalen Spielen siehe die <0>Seite zu Sudoku Hölle</0>.\"],\"_4AR-Z\":[[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" Seiten\"],\"_YA7YX\":[\"Ja, ebenso wie Everest, Platinum Blonde und Golden Nugget. Das Heft druckt die Rätsel so, wie sie ursprünglich veröffentlicht wurden.\"],\"_kK7k_\":[\"Was ist der Unterschied zwischen einem Wing und einer Kette?\"],\"_nkVQD\":[\"Nichts im Heft braucht eine Kette – die beginnt erst mit der Stufe Albtraum.\"],\"_t9fa1\":[\"Was ist Sudoku Unendlich?\"],\"a3pVqb\":[\"Häufig gestellte Fragen\"],\"aF08Xt\":[\"Sieben. Anfänger, Einfach, Mittelschwer, Schwer, Albtraum und Hölle bilden die Technikleiter, jede definiert durch eine Zahl der Vorgaben und ein garantiertes Technikband statt durch ein Marketing-Etikett. Darüber steht Unendlich, eine kuratierte Sammlung von Rekordrätseln, ausgewählt nach veröffentlichter Bewertung.\"],\"aIDRsS\":[\"<0>Mittelschwer.</0> Mit Singles kommt man immer ins Stocken, mit Schnittmengen und Subsets geht es immer weiter – Zeigende Paare, Box-Zeilen-Reduktion, nackte und verdeckte Paare bis Quadrupel.\"],\"aMv0h8\":[\"Ein mittelschweres Rätsel aus demselben Generator wie in der App. Spiele es gleich hier.\"],\"aOHWJD\":[\"<0>Nacktes Single</0> – eine Zelle, in der genau ein Kandidat übrig bleibt.\"],\"aQ3vvP\":[[\"nightmareClueCount\"],\" Vorgaben; mit Wings kommt man garantiert nicht weiter, mit Ketten und Färben schon. Zum digitalen Spielen siehe die <0>Seite zu Sudoku Albtraum</0>.\"],\"aeZiiA\":[\"Jedes Rätsel hat garantiert genau eine Lösung, ganz ohne Raten\"],\"agPptk\":[\"Mittelschwer\"],\"ajKnoT\":[\"Die drei Regeln von Sudoku\"],\"alOHPr\":[\"Sollen Schnittmengen und Subsets anfangen zu zählen? Geh weiter zum <0>druckbaren Sudoku-Heft Mittelschwer</0> oder zurück zu <1>Sudoku für Anfänger zum Ausdrucken</1> für ein noch sanfteres Gitter. Um einfache Rätsel stattdessen am Bildschirm zu spielen, besuche die <2>Seite zu Sudoku Einfach</2>.\"],\"bIMckF\":[\"Das Standard-PDF nutzt bereits ein großzügiges Layout mit \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" Rätseln pro Seite. Für noch größere Zellen siehe das <0>druckbare Sudoku-Heft Einfach</0>, das auch die Ausgangsstufe für unser Großdruck-PDF ist.\"],\"bJo3n2\":[\"Sudoku-Tipps\"],\"bLowF0\":[\"Deine ersten Zellen lösen\"],\"bMqX8c\":[\"Nach fehlenden Ziffern in Einheiten suchen\"],\"bQP2nt\":[\"Löst du einfache Rätsel, ohne zu einem verdeckten Single zu greifen? Geh zurück zu <0>Sudoku für Anfänger</0> oder weiter zu <1>Sudoku Mittelschwer</1>, wo Schnittmengen und deine ersten Paare auftauchen. Lieber auf Papier? Lade das <2>druckbare Sudoku-Heft Einfach</2> herunter oder lies den Ratgeber <3>Sudoku für Senioren</3> mit Optionen für Großdruck und Komfort. Sieh dir das vollständige <4>Technikverzeichnis</4>, die <5>Spielanleitung</5> oder alle Stufen in der Übersicht <6>Sudoku-Schwierigkeitsstufen</6> an, oder gehe zurück zur <7>Startseite</7>.\"],\"bUGU7d\":[\"Größe und Form. Ein Wing ist ein festes Muster aus drei oder vier Zellen, das man auf einen Blick erkennen lernt; eine Kette wird Glied für Glied aufgebaut und kann beliebig lang werden, weshalb Ketten auf der SE-Skala ein ganzes Band über Wings liegen.\"],\"bVG9Tb\":[\"Zum Ausdrucken\"],\"bY8tm0\":[\"Quellcode auf GitHub\"],\"bc8DGE\":[\"Fülle jede leere Zelle mit einer Ziffer von 1 bis 9, sodass sich keine Ziffer in einer Zeile, einer Spalte oder einem 3×3-Block wiederholt.\"],\"c38U12\":[\"Was ist ein Zeigendes Paar?\"],\"c3R2ID\":[\"Letzte freie Zelle und Nacktes Single sind die ersten beiden Strategien, die die Löse-Engine von Suuudokuuu bei jedem Rätsel jeder Stufe ausprobiert, weil sie die am billigsten zu prüfenden Folgerungen sind. Anfänger zeichnet aus, dass die Stufe genau aus den Rätseln besteht, die nie etwas anderes brauchen. Entfernt man mehr Ziffern, bleibt ein Löser irgendwann ohne verdeckte Singles, Schnittmengen oder Subsets stecken, und der Generator verwirft solche Rätsel, statt sie als Anfänger zu kennzeichnen. Wer in einer Zeile die eine fehlende Ziffer benennen kann, hat bereits alle Fähigkeiten, die ein Anfänger-Rätsel verlangt.\"],\"cK6miM\":[\"Schwierigkeit\"],\"cVxfVr\":[\"Nein. Beide Techniken, die ein Anfänger-Rätsel braucht, lassen sich direkt vom Brett ablesen – genau deshalb sind sie die schnellsten Folgerungen im Spiel.\"],\"d4hJrp\":[\"Schwerere Stufe\"],\"d5hiJp\":[\"Warum Spieler bleiben\"],\"dKAb7E\":[\"Jedes Höllen-Rätsel braucht eine Zwangskette: Keines lässt sich mit den Techniken lösen, die Albtraum erlaubt, bis hin zu AIC.\"],\"dXoieq\":[\"Zusammenfassung\"],\"do-_4n\":[\"Mindestens ein Fish (<0>X-Wing</0> und seine größeren und Finned-Verwandten) oder ein Wing-Muster mit zwei Kandidaten, zusätzlich zu allen Schnittmengen und Subsets, die schon die leichteren Hefte verlangen.\"],\"dvRtE-\":[\"Sieben: Anfänger, Einfach, Mittelschwer, Schwer, Albtraum, Hölle und Unendlich. Höllen-Rätsel stammen aus einem mitgelieferten, geprüften Korpus von Rätseln, die jeweils eine Zwangskette brauchen, mehr als alles, was Albtraum verlangt, und <0>Unendlich</0> bietet Rekordrätsel wie Everest und AI Escargot.\"],\"dyGlGe\":[\"Der Großdruck-Satz nutzt dieselbe Logik der Stufe Einfach wie das Heft oben, aber mit \",[\"PRINTABLE_LARGE_PRINT_PUZZLES_PER_PAGE\"],\" Rätseln pro Seite statt \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\", sodass jede Zelle und jede Ziffer spürbar größer gedruckt wird. Er eignet sich für Löser mit Sehschwäche, für Unterrichtsmaterial, das aus der Entfernung gelesen wird, und für alle, denen das Standardgitter auf Papier zu eng ist. Auf der Seite <0>Sudoku in Großdruck</0> findest du Drucktipps und die Alternative am Bildschirm, im Ratgeber <1>Sudoku für Senioren</1> die vollständige Übersicht mit Schwerpunkt Komfort.\"],\"e0NrBM\":[\"Projekt\"],\"eBV_Xh\":[\"Albtraum-Rätsel haben \",[\"clueCount\"],\" Vorgaben und brauchen garantiert mindestens eine Ketten- oder Färbetechnik jenseits aller Fische und Wings.\"],\"eJ9n-i\":[\"Das Gitter selbst ist neu für dich? Beginne mit der <0>Spielanleitung</0> für die drei Regeln und deine ersten Platzierungen, bevor du oben eine Stufe wählst.\"],\"eJum-4\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" Rätsel auf \",[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" Seiten, gedruckt mit \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite und den gelösten Gittern am Ende.\"],\"emFA81\":[\"FAQ zum druckbaren Sudoku Albtraum\"],\"enA4B7\":[\"Ist Sudoku Schwer schwerer als Albtraum?\"],\"eo2JDj\":[\"Steckst du bei einem Rätsel fest?\"],\"eozBux\":[\"Nicht unbedingt. Höllen-Rätsel haben \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" bis \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" Vorgaben, stammen aus einem mitgelieferten, von zwei unabhängigen Lösungsalgorithmen geprüften Korpus und sind auf Rätsel gefiltert, die eine Zwangskette brauchen, statt zum Druckzeitpunkt frisch erzeugt zu werden.\"],\"ev-7sc\":[\"Nein. Schwer endet beim W-Wing; Albtraum beginnt dort, wo Schwer aufhört, und reicht bis zu alternierenden Schlussketten. Die beiden Stufen trennt eine Technikgrenze, nicht die Zahl der Vorgaben.\"],\"evANQd\":[\"Ketten- und Färbetechniken: X-Chain, XY-Chain, Einfaches Färben und AIC.\"],\"f0OFpM\":[\"<0>Hölle.</0> Mit Ketten und AIC kommt man immer ins Stocken und braucht immer eine Zwangskette, entnommen einem mitgelieferten, geprüften Korpus.\"],\"fRl01D\":[\"Sudoku zum Ausdrucken\"],\"fUYszb\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" Rätsel, \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite gedruckt, mit vollständigem Lösungsteil.\"],\"fY_UvT\":[\"Dies ist das Heft für eine kurze tägliche Gewohnheit statt für eine lange Sitzung: in ein Notizbuch legen, ein Gitter nach dem anderen lösen, und es gibt nie einen Kandidaten aufzuschreiben oder ein Paar quer durch die Zeile zu verfolgen. Es passt auch für eine Klasse, die zum ersten Mal die Regeln kennenlernt, denn eine ganze Klasse kann im selben kurzen Zeitfenster ein Rätsel beenden, ohne dass jemand an einer Schnittmenge hängen bleibt, die noch nicht erklärt wurde. Das Layout mit \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite lässt jedes Gitter groß genug, um bequem hineinzuschreiben, auch mit Kinderhandschrift, und der Lösungsschlüssel hinten bedeutet, dass eine Lehrkraft das Blatt nie selbst lösen muss, um es zu kontrollieren.\"],\"fiJRay\":[\"Mindestens ein <0>Zeigendes Paar</0>, eine <1>Box-Zeilen-Reduktion</1> oder ein nacktes oder verdecktes Paar, zusätzlich zu den Singles, die schon die leichteren Hefte nutzen. Nichts braucht einen Fish, einen Wing oder eine Kette.\"],\"g4WRV6\":[[\"hellCorpusSize\"],\" geprüfte Rätsel mit \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" bis \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" Vorgaben, entnommen dem tdoku-Katalog der 17-Vorgaben-Rätsel und der magictour-Liste top1465, statt sie frisch zu erzeugen.\"],\"g5Fk5U\":[\"Schwer\"],\"gJOrtn\":[\"Schwierigkeitsstufen\"],\"gh-p06\":[[\"clueCount\"],\" Vorgaben bei 81 Zellen; mit Singles allein kommt man garantiert nicht durch, mit einer Schnittmenge oder einem Subset schon.\"],\"gmWGv_\":[\"Eine Kette hat keine feste Form. Deshalb hilft das Markieren mit Bleistift hier mehr als bei den leichteren Stufen.\"],\"gqWp2B\":[\"Eine Kette hat keine feste Form: Sie wird Glied für Glied aufgebaut, und der einzige Weg, den Überblick zu behalten, ist, sie aufzuschreiben. Auf Papier kann man jede starke und schwache Verknüpfung beim Lösen markieren, dem Wechsel bis zum anderen Ende folgen und sofort sehen, welche Zellen beide Enden sehen. Auf einem Handybildschirm, den man scrollen muss, ist das wirklich umständlich. Außerdem ist dies das Heft, in dem sich eine falsche Eliminierung am stärksten auswirkt: Streicht man einen Kandidaten, der hätte bleiben müssen, ist jedes weitere Glied unsicher. Betrachte die Lösungsseiten daher als echte Kontrolle und nicht als Formsache.\"],\"h4IqRM\":[\"Schon sicher bei Schnittmengen und Subsets? Dann geh weiter zu <0>Sudoku Schwer</0>, wo immer ein Fish oder ein Wing nötig ist, oder zurück zu <1>Sudoku Einfach</1>, um Singles zu wiederholen. Lieber auf Papier? Lade das <2>druckbare Sudoku-Heft Mittelschwer</2> herunter. Stöbere im <3>Technikverzeichnis</3>, in der <4>Spielanleitung</4>, in der Übersicht <5>Sudoku-Schwierigkeitsstufen</5> mit allen Stufen oder gehe zurück zur <6>Startseite</6>.\"],\"h6WxWJ\":[\"Gut für ein entspanntes Lösen\"],\"h7hJl_\":[\"Wie schwer diese Rätsel sind\"],\"hw66JY\":[\"Rätsel 1 aus dem Heft Einfach, eines von \",[\"PRINTABLE_BOOKLET_SIZE\"],\" im PDF.\"],\"i0qMbr\":[\"Start\"],\"i7-8lN\":[\"Technikbewusste Hinweise, die das genaue Lösungsmuster benennen und nicht nur die nächste Ziffer\"],\"iDOJbu\":[\"Ein Fish erstreckt sich über ganze Zeilen oder Spalten und lässt sich leichter nachvollziehen, wenn man die verbleibenden Positionen einer Ziffer entlang einer gedruckten Spalte markiert, als wenn man auf dem Bildschirm scrollt. Wings erfordern die umgekehrte Sicht – einige Zellen mit zwei Kandidaten auf einen Blick.\"],\"iEH6te\":[\"<0>Verdecktes Single</0> – eine Ziffer, die in einer Einheit nur in eine einzige Zelle passt.\"],\"iggj45\":[\"Wie schwer ist Sudoku Einfach?\"],\"ippIMU\":[\"Diese zusätzlichen leeren Zellen gegenüber Anfänger genügen, dass sich das Gitter nicht mehr allein durch <0>letzte freie Zellen</0> füllt. Gehen die offensichtlichen Platzierungen aus, lässt ein einfaches Rätsel immer mindestens eine Zelle übrig, bei der nur das Denken in verdeckten Singles weiterführt – prüfe die fehlenden Ziffern jeder Einheit darauf, wo sie noch legal hinpassen, statt Kandidaten direkt aus einer einzelnen Zelle zu lesen. Die Technik-Engine von Suuudokuuu probiert das verdeckte Single als dritte Technik, direkt nach der letzten freien Zelle und dem <1>nackten Single</1>, und ein als Einfach eingestuftes Rätsel braucht nie mehr: keine Zeigenden Paare, keine Subsets, nichts, das verlangt, mehr als eine Einheit gleichzeitig im Kopf zu halten. Der Abstand zwischen den Stufen ist absichtlich klein – er ist genau eine Technik breit.\"],\"iu7tUI\":[\"Brotkrumennavigation\"],\"iuw_bf\":[\"Schwierigkeitsbewertung\"],\"iyTmPq\":[\"Jede benannte Technik ist ein schnellerer Weg, dieselbe Überlappung aus Zeile, Spalte und Block über viele Zellen gleichzeitig zu verfolgen.\"],\"j2fzAU\":[\"Die SE-Bewertungen sind die Werte, die unabhängige Rater und die Sudoku-Löser-Community veröffentlichen. Der Rater von Suuudokuuu meldet für alles Schwerere \",[\"SE_RATING_CEILING\"],\" mit einem Obergrenzen-Hinweis und liefert deshalb für diese Rätsel keinen eigenen Wert.\"],\"j2t1NI\":[\"Jede Stufe verlinkt auf eine eigene Seite mit einer spielbaren Vorschau und den ehrlichen Schwierigkeitsangaben aus unserem <0>Ratgeber zur Sudoku-Schwierigkeit</0>. Für das PDF selbst braucht man nur einen Drucker.\"],\"jFRHhT\":[\"<0>Unendlich</0> – \",[\"infinityCorpusSize\"],\" der schwersten je veröffentlichten Rätsel, ausgewählt nach ihrer veröffentlichten SE-Bewertung von \",[\"infinityLowestRating\"],\" bis \",[\"infinityHighestRating\"],\" statt nach einem Technikband und jenseits der Reichweite jeder Technik auf der Leiter.\"],\"jJ8CSk\":[\"Unsere Stichprobe von \",[\"sampleSize\"],\" schweren Rätseln misst SE \",[\"seRatingRange\"],\".\"],\"jMk3uh\":[\"Such nicht zuerst nach der schwersten Zelle. Beginne mit den leichtesten Platzierungen, denn wenn du sie zuerst erledigst, werden auch alle späteren Zellen leichter.\"],\"jP5seF\":[\"Lerne die Techniken in der Reihenfolge ihrer Schwierigkeit, statt alle Muster auf einmal auswendig zu lernen. Das <0>Verzeichnis der Sudoku-Techniken</0> listet sie von der letzten freien Zelle bis zu den Subset-Mustern auf, jeweils mit einem durchgerechneten Beispiel.\"],\"jmetfY\":[\"Brauchen einfache Rätsel jemals Notizen?\"],\"juLzrc\":[\"Einfach ist die erste Stufe, auf der Suuudokuuu eine echte, wenn auch sanfte Lösung erwartet. Ein einfaches Rätsel hat \",[\"clueCount\"],\" Vorgaben bei 81 Zellen, einige weniger als Anfänger. Letzte freie Zellen und nackte Singles füllen noch den größten Teil des Gitters, aber nie alles: Mindestens eine Zelle braucht immer ein <0>verdecktes Single</0>, bei dem eine Ziffer nur in eine Zelle einer Zeile, Spalte oder eines Blocks passt, obwohl diese Zelle noch andere Kandidaten zeigt. Dieses eine zusätzliche Muster ist der ganze Schritt von Anfänger zu Einfach, und er ist eine Garantie und keine Tendenz: Ein Rätsel, das ein Löser mit nur letzten freien Zellen und nackten Singles beenden kann, wird als zu leicht für die Stufe verworfen, und eines, das mehr als das verdeckte Single braucht, als zu schwer.\"],\"jwpEc6\":[\"Wenn die einfachen Platzierungen ausgehen, wird das Verfolgen von Kandidaten von Hand unverzichtbar. Ein Kandidat, manchmal auch Bleistiftnotiz genannt, ist eine Ziffer, die eine Zelle nach dem, was ihre Zeile, Spalte und ihr Block bereits enthalten, noch legal aufnehmen könnte. Schreibt man jeden Kandidaten in die Zelle – auf Papier als kleine Ziffern in der Ecke oder in einer App mit dem Notizmodus –, wird aus einem scheinbar festgefahrenen Rätsel eines, in dem Muster sichtbar werden: Paare, Tripel und Quadrupel von Kandidaten, die sich in einer Einheit wiederholen, sind genau das, was Techniken wie nackte und verdeckte Paare erkennen sollen. Die vollständige Methode für jedes Muster steht im <0>Verzeichnis der Sudoku-Techniken</0>, und jeder in diesen Ratgebern verwendete Begriff ist im <1>Sudoku-Glossar</1> erklärt.\"],\"kFGAW9\":[\"Machen wenige Vorgaben diese Rätsel schwer?\"],\"kV-GNp\":[\"<0>Mittelschwer</0> – \",[\"mediumClueCount\"],\" Vorgaben; mit Singles kommt man garantiert nicht weiter, mit Schnittmengen und Subsets schon.\"],\"kbLXsu\":[\"Lösungen auf den letzten Seiten enthalten\"],\"kc2u3T\":[\"Kandidaten Zelle für Zelle streichen\"],\"lAIHWp\":[\"<0>Schwer</0> – \",[\"hardClueCount\"],\" Vorgaben; mit Subsets kommt man garantiert nicht weiter, mit Fish- und Wing-Mustern schon.\"],\"lDdTS6\":[\"FAQ zum druckbaren Sudoku Mittelschwer\"],\"lINilK\":[\"Das PDF beginnt mit einem Deckblatt, das die Anzahl der Rätsel und Seiten nennt, geht über in \",[\"PRINTABLE_BOOKLET_SIZE\"],\" Rätsel mit \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite und schließt mit allen gelösten Gittern auf den letzten Seiten, sodass Antworten nie neben einem ungelösten Rätsel stehen. Jedes Gitter ist mit Vektorlinien und der PDF-Standardschrift Helvetica gezeichnet, bleibt also in jeder Druckgröße scharf und hängt nie von einem gescannten Bild ab. Unsere veröffentlichte Stichprobe von \",[\"sampleSize\"],\" Anfänger-Rätseln misst SE \",[\"seRatingRange\"],\" – Werte, die der <0>Ratgeber zur Sudoku-Schwierigkeit</0> direkt misst, statt sie anzunehmen.\"],\"lPXkj-\":[\"Kann ich dieses Anfänger-Heft in Großdruck ausdrucken?\"],\"lQAsJI\":[\"<0>Spaltenregel.</0> Jede der neun Spalten muss die Ziffern 1 bis 9 genau einmal enthalten.\"],\"laMpeD\":[\"Albtraum\"],\"llBUQM\":[\"Funktioniert nach der Installation vollständig offline, auf iOS, Android und im Web\"],\"lxRnL8\":[\"<0>Blockregel.</0> Jeder der neun 3×3-Blöcke muss die Ziffern 1 bis 9 genau einmal enthalten.\"],\"lzXj7Z\":[\"Jedes Rätsel in diesem Heft braucht eine Zwangskette: Keines lässt sich mit den Techniken beenden, die Albtraum erlaubt, und jedes stammt aus unserem mitgelieferten, unabhängig geprüften Höllen-Korpus und wurde nicht frisch erzeugt. Unsere veröffentlichte Stichprobe von \",[\"sampleSize\"],\" Rätseln misst die Stufe mit SE \",[\"seRatingRange\"],\", mit <0/> als häufigstem schwersten Schritt. Im <1>Ratgeber zu 17-Vorgaben-Sudokus</1> steht, warum nicht die Zahl der Vorgaben sie schwer macht.\"],\"mDD4iI\":[\"Ja, ohne Konto und ohne Wasserzeichen, und das gelöste Gitter jedes Rätsels steht hinten im Heft.\"],\"mOCJOb\":[\"Schon ein paar Albtraum-Rätsel gelöst? <0>Sudoku Hölle</0> ist die letzte Stufe, in der jedes Rätsel eine Zwangskette braucht. Geh zurück zu <1>Sudoku Schwer</1>, wenn sich Fische und Wings noch unsicher anfühlen. Lieber auf Papier? Lade das <2>druckbare Sudoku-Heft Albtraum</2> herunter. Stöbere im <3>Technikverzeichnis</3>, in der <4>Spielanleitung</4>, in der Übersicht <5>Sudoku-Schwierigkeitsstufen</5> mit allen Stufen oder gehe zurück zur <6>Startseite</6>.\"],\"mVu64h\":[\"Anfänger-Rätsel haben \",[\"clueCount\"],\" Vorgaben und lassen sich garantiert allein mit letzten freien Zellen und nackten Singles beenden.\"],\"m_1uBm\":[\"Tägliches Sudoku\"],\"mbw3Zs\":[\"Welche Schwierigkeitsstufen gibt es?\"],\"mdr9O2\":[[\"PRINTABLE_BLANK_GRID_PAGE_COUNT\"],\" Seiten\"],\"mf-vQH\":[[\"newbieClueCount\"],\" Vorgaben, allein mit letzten freien Zellen und nackten Singles lösbar. Zum digitalen Spielen siehe die <0>Seite zu Sudoku für Anfänger</0>.\"],\"mqvuZQ\":[\"Lösen lernen\"],\"n8c99d\":[\"Sudoku-Löser\"],\"ngqvTg\":[\"Teilbare Rätsel-Links und vollständige Wiederholungen jeder Lösung\"],\"o83Dls\":[\"Einfache Rätsel haben \",[\"clueCount\"],\" Vorgaben und brauchen garantiert mindestens ein verdecktes Single, aber nichts Schwierigeres.\"],\"o8ErsC\":[\"Kann ein Sudoku zwei Lösungen haben?\"],\"oACpQU\":[\"Ratgeber zur Schwierigkeit\"],\"oF5_MF\":[\"Große Textgröße\"],\"oFKMy-\":[\"Auf Papier noch nicht bereit für Ketten? Geh zurück zum <0>druckbaren Sudoku-Heft Albtraum</0> für dieselbe Kettenlogik bei mehr vorgegebenem Gitter oder zu <1>Sudoku Schwer zum Ausdrucken</1> für Fische und Wings ohne Kettenlogik, oder spiele die Hölle am Bildschirm auf der <2>Seite zu Sudoku Hölle</2>, wo derselbe Korpus jedes Rätsel liefert. Bereit für die Rekordrätsel? Das <3>druckbare Sudoku-Heft Unendlich</3> druckt Everest, AI Escargot und weitere Rekordgitter.\"],\"oH36ji\":[\"Haben Unendlich-Rätsel eine eindeutige Lösung?\"],\"oQ8R9m\":[\"Muss man bei Albtraum-Rätseln jemals raten?\"],\"oSfAuO\":[\"Sudoku Mittelschwer\"],\"o_ys4H\":[\"Jedes Anfänger-Rätsel wird im Moment seiner Erstellung auf der SE-Skala (Sudoku Explainer) bewertet. Unsere veröffentlichte Stichprobe von \",[\"sampleSize\"],\" Anfänger-Rätseln misst SE \",[\"seRatingRange\"],\" – ganz unten auf einer Skala, die bis 12 reicht, und unterhalb dessen, was die meisten SE-Tabellen überhaupt benennen. Anfänger soll die Überlappung von Zeile, Spalte und Block vermitteln, auf der jede spätere Technik aufbaut, und sie nicht prüfen. Den gemessenen Bereich dieser und jeder anderen Stufe veröffentlichen wir in unserem <0>Ratgeber zur Sudoku-Schwierigkeit</0>. Betrachte eine schnelle, fehlerfreie Anfänger-Lösung als Bestätigung, dass du für Einfach bereit bist, und nicht als Maßstab, den man um seiner selbst willen anstreben müsste.\"],\"oc75Be\":[\"Ein wohlgeformtes Sudoku nie. Hat ein Rätsel mehr als eine gültige Lösung, gilt es als fehlerhaft, weil die Logik allein nicht mehr auf eine einzige Antwort führt.\"],\"ohi_6A\":[\"Prüfe für jede Einheit mit mehreren leeren Zellen, ob eine Ziffer, die in der Einheit noch fehlt, nur in eine davon passt – auch wenn diese Zelle noch andere Kandidaten hat.\"],\"p6O9l-\":[\"Wie viele Rätsel enthält das druckbare Sudoku-PDF Unendlich?\"],\"p95wx0\":[\"Letzte freie Zellen und Singles als Grundlage, dazu Zeigende Paare, Zeigende Triplets, Box-Zeilen-Reduktion und die nackten oder verdeckten Subsets bis zu Quadrupeln, wann immer die Singles ausgehen. Mindestens eine davon ist immer nötig, und nie etwas Schwierigeres.\"],\"pDFJMU\":[\"Lade das PDF herunter, öffne es in einem beliebigen PDF-Programm und drucke es in 100 % Größe auf US-Letter-Papier. Jedes Gitter besteht aus Vektorlinien und Standard-PDF-Schriften, es gibt also nichts zu rastern und bei keiner Druckgröße einen Qualitätsverlust.\"],\"pIksP6\":[\"FAQ zu Sudoku Unendlich\"],\"pN5c2M\":[\"Sudoku Albtraum\"],\"pOHwnD\":[\"Welche Techniken verlangt dieses Heft Mittelschwer?\"],\"pXows4\":[\"Suuudokuuu hat sieben Schwierigkeitsstufen: sechs, die jeweils ein breiteres Technikspektrum verlangen als die vorherige, und Unendlich.\"],\"pe908p\":[\"Eine Vorgabe (englisch Clue oder Given) ist eine Ziffer, die vor dem Start bereits auf dem Brett steht. Ein Kandidat ist eine Ziffer, die du für eine leere Zelle noch in Betracht ziehst, je nachdem, was ihre Zeile, Spalte und ihr Block gerade ausschließen.\"],\"plp0e4\":[\"Sudoku Albtraum jetzt spielen\"],\"pu3rE1\":[\"Mit \",[\"clueCount\"],\" Vorgaben bei 81 Zellen ist dieses Heft das erste, das man mit dem Bleistift lösen sollte. Singles tragen ein mittelschweres Gitter ein Stück weit, doch jedes Rätsel darin bleibt nachweislich an ihnen hängen – das ist der Test, den jedes Rätsel nicht bestehen durfte, um hier gedruckt zu werden –, bis man ein <0>Zeigendes Paar</0> oder eine <1>Box-Zeilen-Reduktion</1> entdeckt, eine Schnittmenge zwischen einem Block und einer Linie, die nur Kandidaten streicht und nie eine Ziffer setzt. Nichts im Heft braucht einen Fish, einen Wing oder eine Kette.\"],\"q7QiGX\":[\"Spielanleitung\"],\"qcBjCp\":[\"<0>Albtraum</0> – \",[\"nightmareClueCount\"],\" Vorgaben; mit Wings kommt man garantiert nicht weiter, mit Ketten und Färben schon.\"],\"qiqtfW\":[\"Sudoku Mittelschwer jetzt spielen\"],\"qrmik6\":[[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" Rätsel\"],\"qwJuVW\":[\"Fußbereich\"],\"qyiPQ_\":[\"Einfach ist das Heft, zu dem man greift, wenn man ein Rätsel lösen will, ohne lange angestrengt nachzudenken – im Zug, in der Kaffeepause oder zum Abschalten vor dem Schlafengehen. Jede Folgerung lässt sich noch vom Brett ablesen statt aus einem Kandidatengitter, es gibt also selten einen Grund, Kandidaten an den Rand zu schreiben; das verdeckte Single verlangt, eine ganze Einheit statt einer einzelnen Zelle abzusuchen, was eine Änderung der Gewohnheit ist und keine der Schwierigkeit. Dadurch eignet es sich gut, gleich mehrere auszudrucken und im Lauf einer Woche einen kleinen Stapel abzuarbeiten, denn kein einzelnes Rätsel verlangt die Konzentration eines mittelschweren oder schweren Gitters.\"],\"r2FUkM\":[\"Dieses Rätsel hier spielen\"],\"r4WJmT\":[\"Sudoku-Techniken\"],\"r7ajsb\":[\"Keine Werbung, kein Konto und kein Tracking im Spiel, weder im Web noch in der App\"],\"r8BZnz\":[\"Brauche ich Stift und Papier, um Sudoku zu lösen?\"],\"rFkWoz\":[\"Nein. Jedes von Suuudokuuu erzeugte Rätsel wird bei der Erzeugung auf eine eindeutige Lösung geprüft, sodass nie eine Zelle Raten erfordert – und die mitgelieferten Höllen-Rätsel werden vor der Auslieferung zusätzlich von zwei unabhängigen Lösungsalgorithmen gegengeprüft, einem Dancing-Links-Exact-Cover-Löser und einem Bitmasken-Löser. Eine Stellung, die mehrdeutig wirkt, braucht einfach eine Technik, die noch nicht ausprobiert wurde.\"],\"rISE1w\":[\"Welche Techniken brauche ich für Sudoku Mittelschwer?\"],\"rUmdf8\":[\"Ist das druckbare Sudoku-PDF Schwer kostenlos?\"],\"rUv2wg\":[\"Außerdem ist dies die Ausgangsstufe für das Großdruck-PDF mit \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" Rätseln.\"],\"rcYOQY\":[\"Mindestens eine Ketten- oder Färbetechnik – Fische auf <0>Swordfish</0>-Niveau und Wings auf <1>XY-Wing</1>-Niveau genügen allein nicht –, zusätzlich zu jedem Fish und Wing, die schon die Stufe Schwer verlangt.\"],\"rgh2Sh\":[\"Unsere Stichprobe von \",[\"sampleSize\"],\" Albtraum-Rätseln misst SE \",[\"seRatingRange\"],\".\"],\"rhRptr\":[\"Es ist ein echter Schritt nach oben von Einfach, doch jede Technik, die es braucht, funktioniert noch innerhalb eines einzelnen Blocks oder einer einzelnen Linie – die längeren Fish- und Kettenmuster beginnen erst bei Schwer und darüber.\"],\"rjZpLn\":[\"Lernen\"],\"rtx2YX\":[[\"easyClueCount\"],\" Vorgaben, und jedes Rätsel braucht mindestens ein verdecktes Single, aber nie mehr als das. Zum digitalen Spielen siehe die <0>Seite zu Sudoku Einfach</0>.\"],\"sAlGDx\":[\"Kostenlos, quelloffen, keine Werbung\"],\"sMgCJW\":[\"Ein Rätsel, das ein verdecktes Single oder etwas Schwierigeres braucht, wird verworfen und neu erzeugt – es wird nie als Anfänger eingestuft.\"],\"sYhvIH\":[\"<0>Unendlich.</0> Die schwersten je veröffentlichten Sudokus, etwa Everest und AI Escargot, ausgewählt nach ihrer veröffentlichten Bewertung statt nach einem Technikband – siehe die <1>Seite zu Sudoku Unendlich</1>.\"],\"sf_Uq_\":[\"Unsere Stichprobe von \",[\"sampleSize\"],\" Anfänger-Rätseln misst SE \",[\"seRatingRange\"],\".\"],\"sgcKNN\":[\"Jede Sudoku-Regel ist im Grunde dieselbe Bedingung, angewendet auf drei verschiedene Arten von Einheiten. Wer die Bedingung einmal verstanden hat, kennt bereits alle drei Regeln.\"],\"sjwplg\":[\"Jedes Heft unten ist ein kostenloses druckbares Sudoku-PDF, erstellt aus denselben Rätselquellen, die die App spielt – ihrem Generator und den Technik-Detektoren, und für Hölle und Unendlich den mitgelieferten, geprüften Korpora. Wähle eine Stufe für ein Heft mit \",[\"PRINTABLE_BOOKLET_SIZE\"],\" Rätseln und den Lösungen auf den letzten Seiten, oder nimm unten den Großdruck-Satz oder ein leeres Sudoku-Gitter. Ohne Anmeldung, ohne Werbung, ohne Wasserzeichen.\"],\"ssPRl9\":[\"Die schwerste Stufe von Suuudokuuu: \",[\"infinityCorpusSize\"],\" der schwersten je veröffentlichten Sudoku-Rätsel mit je einer veröffentlichten SE-Bewertung von \",[\"minimumRatingLabel\"],\" oder mehr, kostenlos und ohne Werbung spielbar.\"],\"svA7xQ\":[\"Bereit für ein Rätsel, das eine Idee mehr braucht? Geh weiter zu <0>Sudoku Einfach</0>, das zu allem hier das verdeckte Single hinzufügt. Lieber auf Papier? Lade das <1>druckbare Sudoku-Heft für Anfänger</1> herunter oder lies den Ratgeber <2>Sudoku für Senioren</2> mit Optionen für Großdruck und Komfort. Stöbere im vollständigen <3>Technikverzeichnis</3> oder in der <4>Spielanleitung</4>, oder geh zurück zur <5>Startseite</5> und sieh dir alle sieben Stufen in der Übersicht <6>Sudoku-Schwierigkeitsstufen</6> an.\"],\"tHJbOh\":[\"Ist Unendlich schwerer als die Hölle?\"],\"tK6SRc\":[\"Jedes Rätsel braucht eine Zwangskette und stammt aus einem mitgelieferten, unabhängig geprüften Korpus von Rätseln mit \",[\"HELL_CORPUS_MINIMUM_GIVEN_COUNT\"],\" bis \",[\"HELL_CORPUS_MAXIMUM_GIVEN_COUNT\"],\" Vorgaben.\"],\"tYB68O\":[\"Rätsel 1 aus dem Heft Unendlich, eines von \",[\"PRINTABLE_BOOKLET_SIZE\"],\" im PDF.\"],\"tc4WHX\":[\"Bedeuten weniger Vorgaben immer ein schwereres Rätsel?\"],\"thMLRg\":[\"Schwer endet beim W-Wing – ein Rätsel, das sich allen Fischen und Wings widersetzt, wird stattdessen als Albtraum eingestuft.\"],\"uFeI93\":[\"Bei jedem Spiel wird das Gitter neu gemischt, sodass ein bekanntes Rekordrätsel nie zweimal gleich aussieht.\"],\"uJerz5\":[\"Suuudokuuu stuft seine Rätsel auf einer Leiter mit sechs Stufen ein, von Anfänger bis Hölle, und jede Stufe ist durch zwei konkrete Tatsachen definiert statt durch ein Marketing-Etikett: wie viele Vorgaben das Gitter hat und welche benannten Lösungstechniken die Stufe garantiert verlangt. Jedes neue Rätsel wird außerdem im Moment seiner Erstellung auf der SE-Skala (Sudoku Explainer) bewertet, und zwar mit demselben quelloffenen Bewertungspaket, das der <0>Ratgeber zur Sudoku-Schwierigkeit</0> nutzt, um das gemessene Band und den SE-Bereich jeder Leiterstufe darunter zu veröffentlichen. Über der Leiter steht <1>Unendlich</1>, eine kuratierte Sammlung von Rekordrätseln mit den Bewertungen, die unabhängige Rater veröffentlichen, weil sie über das obere Ende unserer eigenen Bewertungsskala hinausreichen.\"],\"uy5vQS\":[\"Tippe oder füge das Gitter in den <0>schrittweisen Sudoku-Löser</0> ein, und er benennt jeden Zug – Verdecktes Single, Nacktes Paar, X-Wing –, statt das Brett einfach auszufüllen. Er prüft zuerst, dass dein Rätsel genau eine Lösung hat, und läuft vollständig in deinem Browser.\"],\"uyJsf6\":[\"Über uns\"],\"v1_ToA\":[\"Schnittmengen und Paare findet man, indem man in einer Einheit jeden verbleibenden Kandidaten markiert. Deshalb lässt das Layout in jeder Zelle gezielt Platz für diese Bleistiftnotizen.\"],\"vAJFgP\":[\"Gut für die erste Sudoku-Gewohnheit\"],\"vEHxJQ\":[\"Sudoku-Schwierigkeitsstufen\"],\"vLhN57\":[\"Unsere Stichprobe von \",[\"sampleSize\"],\" schweren Rätseln misst SE (Sudoku Explainer) \",[\"seRatingRange\"],\" – genau in dem Bereich, den die Löser-Community mit Fish- und Wing-Mustern verbindet, und weit unterhalb des Kettenbereichs über 7. Der häufigste schwerste Schritt ist <0/>, und der schwerste, den irgendein Rätsel der Stichprobe erreichte, ist <1/>. Hier fangen Gelegenheitslöser an, nach einem Hinweis zu greifen: Fish und Wings lassen sich leicht beschreiben und auf einem echten Brett wirklich schwer erkennen, rechne also mit einer spürbar längeren, bedachteren Lösung, als Mittelschwer sie verlangt. Die vollständigen Daten pro Stufe findest du im <2>Ratgeber zur Sudoku-Schwierigkeit</2>.\"],\"vNl4Yu\":[\"Einfach beginnt bei \",[\"clueCount\"],\" Vorgaben, sechs weniger als Anfänger, und ergänzt genau eine Technik: Jedes Rätsel in diesem Heft braucht mindestens ein <0>verdecktes Single</0>, und keines braucht etwas Schwierigeres. Dieses eine zusätzliche Muster macht es zum Heft für ein entspanntes Rätsel in der Kaffeepause und nicht zum Lehrmaterial. Es ist zudem die Ausgangsstufe für unser Großdruck-PDF mit \",[\"PRINTABLE_LARGE_PRINT_SIZE\"],\" Rätseln für Leser, die größere Zellen wollen.\"],\"vXIe7J\":[\"Sprache\"],\"vbOpg_\":[\"Warum \",[\"SITE_NAME\"]],\"viJ4-_\":[\"Unsere Stichprobe von \",[\"sampleSize\"],\" Höllen-Rätseln misst SE \",[\"hellSeRatingRange\"],\".\"],\"vlNS-q\":[\"Anfänger ist die Einsteigerstufe von Suuudokuuu, die sanfteste denkbare Einführung ins Gitter. Ein Anfänger-Rätsel beginnt mit \",[\"clueCount\"],\" der 81 bereits gefüllten Zellen. Jede verbleibende Zelle lässt sich mit den zwei einfachsten Folgerungen des Spiels finden: einer <0>letzten freien Zelle</0>, bei der in einer Einheit nur noch eine leere Zelle übrig ist, und einem <1>nackten Single</1>, bei dem Zeile, Spalte und Block einer Zelle zusammen bereits acht der neun Ziffern erklären. Das beschreibt nicht etwa ein typisches Anfänger-Rätsel – es ist die Regel, die der Generator durchsetzt: Ein Kandidatenrätsel wird nur dann als Anfänger akzeptiert, wenn ein auf letzte freie Zellen und nackte Singles beschränkter Löser es beendet hat. Notizen, Eliminierungslogik und Raten sind nie nötig.\"],\"voLlG5\":[\"So beginnst du, ein Sudoku zu lösen\"],\"vsge_o\":[\"Neu bei Sudoku?\"],\"vvCT_r\":[\"Wie es weitergeht\"],\"vwz0Q4\":[\"PDF, \",[\"fileSizeKilobytes\"],\" KB, US Letter\"],\"wIwe3l\":[\"So ist die Leiter aufgebaut\"],\"wT9V53\":[\"Mittelschwer ist die Stufe, auf der Suuudokuuu anfängt, Notizen zu verlangen. Ein mittelschweres Rätsel hat \",[\"clueCount\"],\" Vorgaben bei 81 Zellen, und Singles allein beenden es nachweislich nie: Jedes Rätsel der Stufe wurde gegen einen Löser nur mit Singles geprüft und verworfen, wenn dieser Löser durchkam. Sobald letzte freie Zellen und Singles ausgehen, stockt das Rätsel, bis man eine Schnittmenge – eine Ziffer, die auf die Überlappung von Block und Linie beschränkt ist – oder ein verbundenes Paar entdeckt. <0>Zeigende Paare</0>, <1>Zeigende Triplets</1> und <2>Box-Zeilen-Reduktion</2> decken die Schnittmengen ab; <3>nackte Paare</3> und <4>verdeckte Paare</4> das kleinste Subset-Muster.\"],\"xI2Au1\":[\"Rätsel 1 aus dem Heft Schwer, eines von \",[\"PRINTABLE_BOOKLET_SIZE\"],\" im PDF.\"],\"xRTkBI\":[\"Unendlich\"],\"xTziZu\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" Rätsel auf \",[\"PRINTABLE_BOOKLET_PAGE_COUNT\"],\" Seiten, \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite, mit den gelösten Gittern am Ende.\"],\"xYaf-9\":[\"Ist die Hölle schwerer als Albtraum?\"],\"xkW-Mi\":[\"Warum lässt dieses Heft mehr Platz um jede Ziffer?\"],\"xs4NvR\":[\"Ist \",[\"SITE_NAME\"],\" kostenlos?\"],\"y-GOTe\":[\"Betrachte danach eine einzelne leere Zelle und streiche jede Ziffer, die bereits in ihrer Zeile, Spalte und ihrem Block steht. Bleibt nur eine Ziffer übrig, ist das ein <0>nacktes Single</0>, und du kannst sie sofort eintragen. Hat eine Zelle noch mehrere Kandidaten, prüfe, ob einer davon in derselben Einheit nirgendwo anders hinpasst – das ist ein <1>verdecktes Single</1>, das genauso sicher eingetragen werden kann. Zusammen lösen diese beiden Muster den größten Teil eines einfachen Rätsels ohne tiefergehende Überlegungen.\"],\"yDLr5P\":[\"Großdruck-Sudoku\"],\"yNzy3T\":[\"Unsere Stichprobe von \",[\"sampleSize\"],\" mittelschweren Rätseln misst SE \",[\"seRatingRange\"],\", und \",[\"singlesOnlyPuzzleCount\"],\" von \",[\"sampleSize\"],\" wurden allein mit Singles beendet – dies ist die erste Stufe, auf der diese Zahl konstruktionsbedingt null ist. Der häufigste schwerste Schritt der Stichprobe ist <0/>, und der schwerste, der erreicht wurde, ist <1/>. Wer Bleistiftnotizen flüssig liest, löst ein mittelschweres Rätsel spürbar schneller als Spieler, die Kandidaten im Kopf verfolgen und hier die erste Stufe finden, die das Aufschreiben von Kandidaten wirklich belohnt. Die vollständigen Daten pro Stufe stehen in unserem <2>Ratgeber zur Sudoku-Schwierigkeit</2>.\"],\"y_3zNL\":[\"Letzte freie Zellen und nackte Singles füllen noch den größten Teil des Gitters; das verdeckte Single ist die einzige Ergänzung gegenüber Anfänger.\"],\"yjTW_5\":[\"Welche Techniken brauche ich auf der Stufe Hölle?\"],\"yy8xD2\":[\"Das Gitter selbst ändert sich nie: neun Zeilen, neun Spalten und neun Blöcke, insgesamt einundachtzig Zellen. Was sich von Rätsel zu Rätsel ändert, ist nur, welche Zellen gefüllt beginnen und welche Ziffern sie enthalten, und genau diese Ausgangsverteilung der Vorgaben bestimmt, wie viel Logik nötig ist, um zur einen gültigen Lösung zu gelangen.\"],\"z0P0h9\":[\"Unsere Stichprobe von \",[\"sampleSize\"],\" Höllen-Rätseln misst SE (Sudoku Explainer) \",[\"hellSeRatingRange\"],\", mit <0/> als häufigstem schwersten Schritt und <1/> als schwerstem Schritt, den irgendein Rätsel der Stichprobe erreichte. Lies die Zahl der Vorgaben bitte nicht als Ursache: Dieselbe Stichprobe setzt <2>Albtraum</2> bei SE \",[\"nightmareSeRatingRange\"],\" mit \",[\"nightmareClueCount\"],\" Vorgaben an, und manche Höllen-Rätsel beginnen mit mehr Vorgaben als das. Diese Stufe wurde früher allein aus 17-Vorgaben-Rätseln gebaut und bewertete sich nicht schwerer als Albtraum; erst die Auswahl nach der nötigen Technik trennt die beiden. Unser Ratgeber <3>Vorgaben und Schwierigkeit</3> zerlegt dieses Argument gründlich, und der <4>Bewertungsratgeber</4> veröffentlicht die Tabellen pro Stufe.\"],\"zGCYA8\":[\"Kann ich hier AI Escargot und Everest spielen?\"],\"zX6n8C\":[\"Rekordrätsel wie Everest und AI Escargot, gedruckt wie ursprünglich veröffentlicht. Zum digitalen Spielen siehe die <0>Seite zu Sudoku Unendlich</0>.\"],\"zaRGXY\":[\"Leeres Sudoku-Gitter\"],\"zdhNJO\":[\"FAQ zu Sudoku Mittelschwer\"],\"zu-XZL\":[\"Sudoku Einfach\"],\"zuuvDj\":[[\"PRINTABLE_BOOKLET_SIZE\"],\" Rekordrätsel, \",[\"PRINTABLE_BOOKLET_PUZZLES_PER_PAGE\"],\" pro Seite gedruckt, mit vollständigem Lösungsteil.\"]}")as Messages;